from typing import Any, Callable, List, Optional

import torch
from torch import Tensor, nn
import torch.nn.functional as F
from collections import OrderedDict
from torch.utils.checkpoint import checkpoint_sequential
from torchvision.ops import Conv2dNormActivation


class BasicConv2d(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size=3, stride=1, groups=1, act=True):
        super().__init__()
        padding = (kernel_size - 1) // 2 if isinstance(kernel_size, int) else tuple((k - 1) // 2 for k in kernel_size)
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride,
                              padding=padding, groups=groups, bias=False)
        self.bn = nn.BatchNorm2d(out_channels)
        self.act = nn.Hardswish(inplace=True) if act else nn.Identity()

    def forward(self, feats: Tensor) -> Tensor:
        feats = self.conv(feats)
        feats = self.bn(feats)
        return self.act(feats)


class MBConv(nn.Module):
    def __init__(self, inp, oup, stride, expand_ratio, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super().__init__()
        self.stride = stride
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d

        hidden_dim = int(round(inp * expand_ratio))
        self.use_res_connect = self.stride == 1 and inp == oup

        layers = []
        if expand_ratio != 1:
            layers.append(BasicConv2d(inp, hidden_dim, kernel_size=1))
        layers.append(BasicConv2d(hidden_dim, hidden_dim, kernel_size=3, stride=stride, groups=hidden_dim))

        layers.append(nn.Conv2d(hidden_dim, oup, 1, 1, 0, bias=False))
        layers.append(norm_layer(oup))
        self.conv = nn.Sequential(*layers)

    def forward(self, feats: Tensor) -> Tensor:
        if self.use_res_connect:
            return feats + self.conv(feats)
        return self.conv(feats)


class FireModule(nn.Module):
    def __init__(self, inplanes, squeeze_planes, expand1x1_planes, expand3x3_planes):
        super().__init__()
        self.inplanes = inplanes
        self.squeeze = nn.Conv2d(inplanes, squeeze_planes, kernel_size=1)
        self.expand1x1 = nn.Conv2d(squeeze_planes, expand1x1_planes, kernel_size=1)
        self.expand3x3 = nn.Conv2d(squeeze_planes, expand3x3_planes, kernel_size=3, padding=1)
        self.act = nn.Hardswish(inplace=True)

    def forward(self, feats: Tensor) -> Tensor:
        feats = self.act(self.squeeze(feats))
        return torch.cat(
            [self.act(self.expand1x1(feats)), self.act(self.expand3x3(feats))], 1
        )


def make_divisible(v, divisor=8, min_value=None):
    if min_value is None:
        min_value = divisor
    new_v = max(min_value, int(v + divisor / 2) // divisor * divisor)
    if new_v < 0.9 * v:
        new_v += divisor
    return new_v


class ConvNet(nn.Module):
    def __init__(self, stem_stages, main_stages, in_chans=3, num_classes=10, drop_rate=0.0, width_mult=1.0, norm_layer: Optional[Callable[..., nn.Module]] = None, output_stride=32, **kwargs):
        super().__init__()
        assert output_stride in (8, 16, 32)
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.num_classes = num_classes
        self.conv_stem = nn.Conv2d(in_chans, 16, kernel_size=3, stride=2, padding=1, bias=False)
        self.bn1 = norm_layer(16)
        self.act1 = nn.Hardswish(inplace=True)
        in_ch = 16
        stages = OrderedDict()
        for idx, (t, c, n, stride, se) in enumerate(stem_stages):
            blocks = []
            out_c = make_divisible(c * width_mult, 8)
            for i in range(n):
                blocks.append(MBConv(in_ch, out_c, stride if i == 0 else 1, t))
                in_ch = out_c
            stages[f"stage{idx + 1}"] = nn.Sequential(*blocks)
        for idx, (sq, e, n) in enumerate(main_stages, start=len(stem_stages)):
            blocks = []
            if idx > 0:
                blocks.append(nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True))
            for _ in range(n):
                blocks.append(FireModule(in_ch, sq, e, e))
                in_ch = 2 * e
            stages[f"stage{idx + 1}"] = nn.Sequential(*blocks)
        self.stages = nn.Sequential(stages)
        self.grad_checkpointing = False
        self.conv_head = Conv2dNormActivation(in_ch, 128, kernel_size=1)
        in_ch = 128
        self.classifier = nn.Sequential(OrderedDict([
            ("flatten", nn.Flatten(1)),
            ("drop", nn.Dropout(p=drop_rate)),
            ("fc", nn.Linear(in_ch, num_classes)),
        ]))

    def forward(self, feats: Tensor) -> Tensor:
        feats = self.conv_stem(feats)
        feats = self.bn1(feats)
        feats = self.act1(feats)
        if self.grad_checkpointing and not torch.jit.is_scripting():
            feats = checkpoint_sequential(self.stages, len(self.stages), feats)
        else:
            feats = self.stages(feats)
        feats = self.conv_head(feats)
        feats = feats.mean((-2, -1))
        return self.classifier(feats)


