import torch
import torch.nn as nn
import torch.nn.functional as F
from torch import Tensor
from functools import partial


def adjust_width(width, group_width):
    group_width = min(group_width, width)
    return int(round(width / group_width) * group_width)


class ResBottleneckBlock(nn.Module):
    def __init__(self, in_ch, out_ch, stride, group_width, bottleneck_ratio=1.0, se_ratio=None):
        super().__init__()
        w_b = int(round(out_ch * bottleneck_ratio))
        groups = w_b // group_width
        self.conv_a = nn.Sequential(nn.Conv2d(in_ch, w_b, 1, bias=False), nn.BatchNorm2d(w_b), nn.ReLU6())
        self.conv_b = nn.Sequential(
            nn.Conv2d(w_b, w_b, 3, stride=stride, padding=1, groups=groups, bias=False),
            nn.BatchNorm2d(w_b),
            nn.ReLU6(),
        )
        self.se = None
        self.conv_c = nn.Sequential(nn.Conv2d(w_b, out_ch, 1, bias=False), nn.BatchNorm2d(out_ch))
        self.shortcut = None
        if in_ch != out_ch or stride != 1:
            self.shortcut = nn.Sequential(nn.Conv2d(in_ch, out_ch, 1, stride=stride, bias=False), nn.BatchNorm2d(out_ch))
        self.act = nn.ReLU6()

    def forward(self, x: Tensor) -> Tensor:
        shortcut = x if self.shortcut is None else self.shortcut(x)
        x = self.conv_a(x)
        x = self.conv_b(x)
        if self.se is not None:
            x = self.se(x)
        x = self.conv_c(x)
        return self.act(x + shortcut)


def make_conv3(in_planes, out_planes, stride=1, groups=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=3, stride=stride, padding=1,
                     groups=groups, bias=False)


def make_conv1(in_planes, out_planes, stride=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=1, stride=stride, bias=False)


class ResBlock(nn.Module):
    expansion = 1

    def __init__(self, inplanes, planes, stride=1, shortcut: Optional[nn.Module] = None, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super().__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.c1 = make_conv3(inplanes, planes, stride)
        self.bn1 = norm_layer(planes)
        self.c2 = make_conv3(planes, planes)
        self.bn2 = norm_layer(planes)
        self.relu = nn.ReLU6()
        self.shortcut = shortcut
        self.stride = stride

    def forward(self, x: Tensor) -> Tensor:
        shortcut_out = x

        y = self.c1(x)
        y = self.bn1(y)
        y = self.relu(y)
        y = self.c2(y)
        y = self.bn2(y)

        if self.shortcut is not None:
            shortcut_out = self.shortcut(x)

        y += shortcut_out
        y = self.relu(y)
        return y


class BasicConv2d(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size=3, stride=1, groups=1, act=True):
        super().__init__()
        padding = (kernel_size - 1) // 2 if isinstance(kernel_size, int) else tuple((k - 1) // 2 for k in kernel_size)
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride,
                              padding=padding, groups=groups, bias=False)
        self.bn = nn.BatchNorm2d(out_channels)
        self.act = nn.ReLU6() if act else nn.Identity()

    def forward(self, x: Tensor) -> Tensor:
        x = self.conv(x)
        x = self.bn(x)
        return self.act(x)


class TinyNet(nn.Module):
    def __init__(self, stem_stages, main_stages, in_chans=3, num_classes=1000, drop_rate=0.0, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super().__init__()
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=1e-3)
        self.num_classes = num_classes
        self.stem = BasicConv2d(in_chans, 16, kernel_size=3, stride=2)
        in_ch = 16
        self.feature_info = []
        for idx, (w, d, g) in enumerate(stem_stages):
            blocks = []
            w = adjust_width(w, g)
            for i in range(d):
                blocks.append(ResBottleneckBlock(in_ch, w, 2 if i == 0 else 1, g))
                in_ch = w
            self.add_module(f"stage{idx + 1}", nn.Sequential(*blocks))
            self.feature_info.append(dict(num_chs=in_ch, module=f"stage{idx + 1}"))
        for idx, (planes, n, stride) in enumerate(main_stages, start=len(stem_stages)):
            blocks = []
            downsample = None
            if stride != 1 or in_ch != planes * ResBlock.expansion:
                downsample = nn.Sequential(
                    make_conv1(in_ch, planes * ResBlock.expansion, stride),
                    norm_layer(planes * ResBlock.expansion),
                )
            blocks.append(ResBlock(in_ch, planes, stride, downsample))
            in_ch = planes * ResBlock.expansion
            for _ in range(1, n):
                blocks.append(ResBlock(in_ch, planes))
            self.add_module(f"stage{idx + 1}", nn.Sequential(*blocks))
            self.feature_info.append(dict(num_chs=in_ch, module=f"stage{idx + 1}"))
        self.num_stages = len(stem_stages) + len(main_stages)
        self.num_features = in_ch
        self.drop = nn.Dropout(drop_rate)
        self.fc = nn.Linear(in_ch, num_classes)

    def forward_features(self, x):
        x = self.stem(x)
        for i in range(self.num_stages):
            x = getattr(self, f"stage{i + 1}")(x)
        return x

    def forward_head(self, x, pre_logits: bool = False):
        x = x.mean((2, 3))
        x = x.flatten(1)
        x = self.drop(x)
        return x if pre_logits else self.fc(x)

    def forward(self, x):
        x = self.forward_features(x)
        x = self.forward_head(x)
        return x


def build_model(variant="small", **kwargs):
    cfgs = {"small": ([(16, 1, 16), (32, 2, 16), (56, 1, 16)], [(64, 1, 2), (128, 1, 2)]), "base": ([(16, 1, 16), (32, 2, 16), (56, 1, 16)], [(64, 2, 2), (128, 2, 2)])}
    return TinyNet(*cfgs[variant], **kwargs)


