from typing import Any, Callable, List, Optional

import torch
from torch import Tensor, nn
import torch.nn.functional as F


class Fire(nn.Module):
    def __init__(self, inplanes, squeeze_planes, expand1x1_planes, expand3x3_planes):
        super().__init__()
        self.inplanes = inplanes
        self.reduce = nn.Conv2d(inplanes, squeeze_planes, kernel_size=1)
        self.expand_a = nn.Conv2d(squeeze_planes, expand1x1_planes, kernel_size=1)
        self.expand_b = nn.Conv2d(squeeze_planes, expand3x3_planes, kernel_size=3, padding=1)
        self.squeeze_activation = nn.ReLU()
        self.expand1x1_activation = nn.ReLU()
        self.expand3x3_activation = nn.ReLU()

    def forward(self, inp: Tensor) -> Tensor:
        inp = self.squeeze_activation(self.reduce(inp))
        return torch.cat(
            [self.expand1x1_activation(self.expand_a(inp)), self.expand3x3_activation(self.expand_b(inp))], 1
        )


def make_conv3(in_planes, out_planes, stride=1, groups=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=3, stride=stride, padding=1,
                     groups=groups, bias=False)


def make_conv1(in_planes, out_planes, stride=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=1, stride=stride, bias=False)


class Bottleneck(nn.Module):
    expansion = 4

    def __init__(self, inplanes, planes, stride=1, shortcut: Optional[nn.Module] = None, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super().__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.conv1 = make_conv1(inplanes, planes)
        self.norm1 = norm_layer(planes)
        self.conv2 = make_conv3(planes, planes, stride)
        self.norm2 = norm_layer(planes)
        self.conv3 = make_conv1(planes, planes * self.expansion)
        self.norm3 = norm_layer(planes * self.expansion)
        self.relu1 = nn.ReLU()
        self.relu2 = nn.ReLU()
        self.relu3 = nn.ReLU()
        self.shortcut = shortcut
        self.stride = stride

    def forward(self, inp: Tensor) -> Tensor:
        shortcut_out = inp

        out = self.conv1(inp)
        out = self.norm1(out)
        out = self.relu1(out)
        out = self.conv2(out)
        out = self.norm2(out)
        out = self.relu2(out)
        out = self.conv3(out)
        out = self.norm3(out)

        if self.shortcut is not None:
            shortcut_out = self.shortcut(inp)

        out = out + shortcut_out
        out = self.relu3(out)
        return out


def downsample_conv(in_chs, out_chs, stride=1, norm_layer=None):
    if norm_layer is None:
        norm_layer = nn.BatchNorm2d
    return nn.Sequential(nn.Conv2d(in_chs, out_chs, kernel_size=1, stride=stride, bias=False), norm_layer(out_chs))


def downsample_avg(in_chs, out_chs, stride=1, norm_layer=None):
    if norm_layer is None:
        norm_layer = nn.BatchNorm2d
    pool = nn.AvgPool2d(2, stride, ceil_mode=True, count_include_pad=False) if stride > 1 else nn.Identity()
    return nn.Sequential(pool, nn.Conv2d(in_chs, out_chs, kernel_size=1, stride=1, bias=False), norm_layer(out_chs))


class ConvBNReLU(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size=3, stride=1, groups=1, act=True):
        super().__init__()
        padding = (kernel_size - 1) // 2 if isinstance(kernel_size, int) else tuple((k - 1) // 2 for k in kernel_size)
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride,
                              padding=padding, groups=groups, bias=False)
        self.bn = nn.BatchNorm2d(out_channels)
        self.use_act = act

    def forward(self, inp: Tensor) -> Tensor:
        inp = self.conv(inp)
        inp = self.bn(inp)
        if not self.use_act:
            return inp
        return F.relu(inp, inplace=True)


class ConvNet(nn.Module):
    def __init__(self, early_cfg, late_cfg, in_chans=3, num_classes=1000, drop_rate=0.0, norm_layer: Optional[Callable[..., nn.Module]] = None, down_type='avg', output_stride=32):
        super().__init__()
        assert output_stride in (8, 16, 32)
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.num_classes = num_classes
        self.stem = ConvBNReLU(in_chans, 8, kernel_size=3, stride=2)
        in_ch = 8
        self.feature_info = []
        self.stages = nn.ModuleList()
        for idx, (sq, e, n) in enumerate(early_cfg):
            blocks = []
            if idx > 0:
                blocks.append(nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True))
            for _ in range(n):
                blocks.append(Fire(in_ch, sq, e, e))
                in_ch = 2 * e
            self.stages.append(nn.Sequential(*blocks))
            self.feature_info.append(dict(num_chs=in_ch, module=f"stages.{idx}"))
        for idx, (planes, n, stride) in enumerate(late_cfg, start=len(early_cfg)):
            blocks = []
            downsample = None
            if stride != 1 or in_ch != planes * Bottleneck.expansion:
                down_fn = downsample_avg if down_type == "avg" else downsample_conv
                downsample = down_fn(in_ch, planes * Bottleneck.expansion, stride, norm_layer)
            blocks.append(Bottleneck(in_ch, planes, stride, downsample))
            in_ch = planes * Bottleneck.expansion
            for _ in range(1, n):
                blocks.append(Bottleneck(in_ch, planes))
            self.stages.append(nn.Sequential(*blocks))
            self.feature_info.append(dict(num_chs=in_ch, module=f"stages.{idx}"))
        self.num_features = in_ch
        self.flatten = nn.Flatten(1)
        self.drop = nn.Dropout(drop_rate)
        self.fc = nn.Linear(in_ch, num_classes)

    def forward_features(self, inp):
        inp = self.stem(inp)
        for stage in self.stages:
            inp = stage(inp)
        return inp

    def forward_head(self, inp, pre_logits: bool = False):
        inp = F.adaptive_avg_pool2d(inp, 1)
        inp = self.flatten(inp)
        inp = self.drop(inp)
        return inp if pre_logits else self.fc(inp)

    def forward(self, inp):
        inp = self.forward_features(inp)
        inp = self.forward_head(inp)
        return inp


def _convnet(variant, weights=None, progress=True, **kwargs):
    cfgs = {"small": ([(8, 32, 2), (16, 64, 3), (24, 96, 3)], [(64, 1, 2), (128, 3, 2)]), "base": ([(8, 32, 3), (16, 64, 4), (24, 96, 4)], [(64, 2, 2), (128, 4, 2)])}
    model = ConvNet(*cfgs[variant], **kwargs)
    if weights is not None:
        model.load_state_dict(weights.get_state_dict(progress=progress))
    return model


def create_net(weights=None, progress=True, **kwargs):
    return _convnet('base', weights, progress, **kwargs)


