import torch
from torch import Tensor, nn
import torch.nn.functional as F
from functools import partial
from collections import OrderedDict
from torch.utils.checkpoint import checkpoint_sequential
from torchvision.ops import Conv2dNormActivation


class SqueezeExpand(nn.Module):
    def __init__(self, inplanes, squeeze_planes, expand1x1_planes, expand3x3_planes):
        super().__init__()
        self.inplanes = inplanes
        self.squeeze = nn.Conv2d(inplanes, squeeze_planes, kernel_size=1)
        self.expand1x1 = nn.Conv2d(squeeze_planes, expand1x1_planes, kernel_size=1)
        self.expand3x3 = nn.Conv2d(squeeze_planes, expand3x3_planes, kernel_size=3, padding=1)
        self.squeeze_activation = nn.ReLU(inplace=True)
        self.expand1x1_activation = nn.ReLU(inplace=True)
        self.expand3x3_activation = nn.ReLU(inplace=True)

    def forward(self, tensor: Tensor) -> Tensor:
        tensor = self.squeeze_activation(self.squeeze(tensor))
        return torch.cat(
            [self.expand1x1_activation(self.expand1x1(tensor)), self.expand3x3_activation(self.expand3x3(tensor))], 1
        )


class BasicConv2d(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size=3, stride=1, groups=1, act=True):
        super().__init__()
        padding = (kernel_size - 1) // 2 if isinstance(kernel_size, int) else tuple((k - 1) // 2 for k in kernel_size)
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride,
                              padding=padding, groups=groups, bias=False)
        self.bn = nn.BatchNorm2d(out_channels)
        self.use_act = act
        self.act = nn.ReLU(inplace=True)

    def forward(self, tensor: Tensor) -> Tensor:
        tensor = self.conv(tensor)
        tensor = self.bn(tensor)
        if self.use_act:
            tensor = self.act(tensor)
        return tensor


class InvertedBottleneck(nn.Module):
    def __init__(self, inp, oup, stride, expand_ratio, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super().__init__()
        self.stride = stride
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d

        hidden_dim = int(round(inp * expand_ratio))
        self.residual = self.stride == 1 and inp == oup

        layers = []
        if expand_ratio != 1:
            layers.append(BasicConv2d(inp, hidden_dim, kernel_size=1))
        layers.append(BasicConv2d(hidden_dim, hidden_dim, kernel_size=5, stride=stride, groups=hidden_dim))

        layers.append(nn.Conv2d(hidden_dim, oup, 1, 1, 0, bias=False))
        layers.append(norm_layer(oup))
        self.conv = nn.Sequential(*layers)

    def forward(self, tensor: Tensor) -> Tensor:
        if self.residual:
            return tensor + self.conv(tensor)
        return self.conv(tensor)


class Stem(nn.Module):
    def __init__(self, in_chs, out_chs, norm_layer=nn.BatchNorm2d):
        super().__init__()
        self.conv = nn.Conv2d(in_chs, out_chs, kernel_size=3, stride=2, padding=1, bias=False)
        self.norm = norm_layer(out_chs)
        self.act = nn.ReLU(inplace=True)
        self.pool = nn.MaxPool2d(kernel_size=3, stride=2, padding=1)

    def forward(self, x):
        x = self.conv(x)
        x = self.norm(x)
        x = self.act(x)
        x = self.pool(x)
        return x


def _make_divisible(v, divisor=8, min_value=None):
    if min_value is None:
        min_value = divisor
    new_v = max(min_value, int(v + divisor / 2) // divisor * divisor)
    if new_v < 0.9 * v:
        new_v += divisor
    return new_v


class Classifier(nn.Module):
    def __init__(self, conv_cfg, block_cfg, in_chans=3, num_classes=10, drop_rate=0.0, width_mult=1.0, norm_layer: Optional[Callable[..., nn.Module]] = None, output_stride=32, **kwargs):
        super().__init__()
        assert output_stride in (8, 16, 32)
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=1e-5)
        self.num_classes = num_classes
        self.stem = Stem(in_chans, 16, norm_layer=norm_layer)
        in_ch = 16
        stages = OrderedDict()
        for idx, (sq, e, n) in enumerate(conv_cfg):
            blocks = []
            if idx > 0:
                blocks.append(nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True))
            for _ in range(n):
                blocks.append(SqueezeExpand(in_ch, sq, e, e))
                in_ch = 2 * e
            stages[f"layer{idx + 1}"] = nn.Sequential(*blocks)
        for idx, (t, c, n, stride, se) in enumerate(block_cfg, start=len(conv_cfg)):
            blocks = []
            out_c = _make_divisible(c * width_mult, 8)
            for i in range(n):
                blocks.append(InvertedBottleneck(in_ch, out_c, stride if i == 0 else 1, t))
                in_ch = out_c
            stages[f"layer{idx + 1}"] = nn.Sequential(*blocks)
        self.stages = nn.Sequential(stages)
        self.grad_checkpointing = False
        self.conv_head = Conv2dNormActivation(in_ch, 64, kernel_size=1)
        in_ch = 64
        self.flatten = nn.Flatten(1)
        self.drop = nn.Identity()
        self.fc = nn.Linear(in_ch, num_classes)

    def forward(self, tensor: Tensor) -> Tensor:
        tensor = self.stem(tensor)
        if self.grad_checkpointing and not torch.jit.is_scripting():
            tensor = checkpoint_sequential(self.stages, len(self.stages), tensor)
        else:
            tensor = self.stages(tensor)
        tensor = self.conv_head(tensor)
        tensor = tensor.mean((2, 3), keepdim=True)
        tensor = self.flatten(tensor)
        tensor = self.drop(tensor)
        return self.fc(tensor)


def create_net(variant="small", **kwargs):
    cfgs = {"small": ([(8, 32, 1), (16, 64, 2)], [(6, 32, 2, 2, False), (6, 40, 1, 2, True)]), "base": ([(8, 32, 2), (16, 64, 3)], [(6, 32, 3, 2, False), (6, 40, 2, 2, True)])}
    return Classifier(*cfgs[variant], **kwargs)


