import torch
from torch import nn
from torch.nn import functional as F
from functools import partial
from collections import OrderedDict
from torch.utils.checkpoint import checkpoint_sequential


class ConvBN(nn.Module):
    def __init__(self, in_channels, out_channels, **kwargs):
        super().__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, bias=False, **kwargs)
        self.bn = nn.BatchNorm2d(out_channels, eps=0.001)

    def forward(self, inp):
        inp = self.conv(inp)
        inp = self.bn(inp)
        return F.relu6(inp, inplace=True)


class InvertedBottleneck(nn.Module):
    def __init__(self, inp, oup, stride, expand_ratio, norm_layer=None):
        super().__init__()
        self.stride = stride
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d

        hidden_dim = int(round(inp * expand_ratio))
        self.use_residual = self.stride == 1 and inp == oup

        layers = []
        if expand_ratio != 1:
            layers.append(ConvBN(inp, hidden_dim, kernel_size=1))
        layers.append(ConvBN(hidden_dim, hidden_dim, kernel_size=5, stride=stride, padding=2, groups=hidden_dim))

        layers.append(nn.Conv2d(hidden_dim, oup, 1, 1, 0, bias=False))
        layers.append(norm_layer(oup))
        self.conv = nn.Sequential(*layers)

    def forward(self, inp):
        out = self.conv(inp)
        if self.use_residual:
            out = out + inp
        return out


def shuffle_channels(x, groups):
    batchsize, num_channels, height, width = x.size()
    channels_per_group = num_channels // groups
    x = x.view(batchsize, groups, channels_per_group, height, width)
    x = torch.transpose(x, 1, 2).contiguous()
    x = x.view(batchsize, -1, height, width)
    return x


class ShuffleBlock(nn.Module):
    def __init__(self, inp, oup, stride):
        super().__init__()
        self.stride = stride
        branch_features = oup // 2
        if self.stride > 1:
            self.branch1 = nn.Sequential(
                self.dw_conv(inp, inp, kernel_size=3, stride=self.stride, padding=1),
                nn.BatchNorm2d(inp),
                nn.Conv2d(inp, branch_features, kernel_size=1, bias=False),
                nn.BatchNorm2d(branch_features),
                nn.ReLU(inplace=True),
            )
        else:
            self.branch1 = nn.Sequential()
        self.branch2 = nn.Sequential(
            nn.Conv2d(inp if self.stride > 1 else branch_features, branch_features, kernel_size=1, bias=False),
            nn.BatchNorm2d(branch_features),
            nn.ReLU(inplace=True),
            self.dw_conv(branch_features, branch_features, kernel_size=3, stride=self.stride, padding=1),
            nn.BatchNorm2d(branch_features),
            nn.Conv2d(branch_features, branch_features, kernel_size=1, bias=False),
            nn.BatchNorm2d(branch_features),
            nn.ReLU(inplace=True),
        )

    @staticmethod
    def dw_conv(i, o, kernel_size, stride=1, padding=0, bias=False):
        return nn.Conv2d(i, o, kernel_size, stride, padding, bias=bias, groups=i)

    def forward(self, inp):
        if self.stride == 1:
            x1, x2 = inp.chunk(2, dim=1)
            out = torch.cat((x1, self.branch2(x2)), dim=1)
        else:
            out = torch.cat((self.branch1(inp), self.branch2(inp)), dim=1)
        out = shuffle_channels(out, 2)
        return out


def _make_divisible(v, divisor=8, min_value=None):
    if min_value is None:
        min_value = divisor
    new_v = max(min_value, int(v + divisor / 2) // divisor * divisor)
    if new_v < 0.9 * v:
        new_v += divisor
    return new_v


class TinyNet(nn.Module):
    def __init__(self, cfg_a, cfg_b, in_chans=3, num_classes=1000, drop_rate=0.0, width_mult=1.0, norm_layer=None, output_stride=32):
        super().__init__()
        assert output_stride in (8, 16, 32)
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=0.001)
        self.num_classes = num_classes
        self.stem = ConvBN(in_chans, 16, kernel_size=3, stride=2, padding=1)
        in_ch = 16
        self.feature_info = []
        stages = OrderedDict()
        for idx, (t, c, n, stride, se) in enumerate(cfg_a):
            blocks = []
            out_c = _make_divisible(c * width_mult, 8)
            for i in range(n):
                blocks.append(InvertedBottleneck(in_ch, out_c, stride if i == 0 else 1, t))
                in_ch = out_c
            stages[f"stage{idx + 1}"] = nn.Sequential(*blocks)
            self.feature_info.append(dict(num_chs=in_ch, module=f"stages.stage{idx + 1}"))
        for idx, (c, n) in enumerate(cfg_b, start=len(cfg_a)):
            blocks = []
            blocks.append(ShuffleBlock(in_ch, c, 2))
            for _ in range(n - 1):
                blocks.append(ShuffleBlock(c, c, 1))
            in_ch = c
            stages[f"stage{idx + 1}"] = nn.Sequential(*blocks)
            self.feature_info.append(dict(num_chs=in_ch, module=f"stages.stage{idx + 1}"))
        self.stages = nn.Sequential(stages)
        self.grad_checkpointing = False
        self.num_features = in_ch
        self.drop = nn.Dropout(drop_rate)
        self.fc = nn.Linear(in_ch, num_classes)

    def forward_features(self, inp):
        torch._assert(inp.dim() == 4, f"expected a 4D input, got {inp.dim()}D")
        inp = self.stem(inp)
        if self.grad_checkpointing and not torch.jit.is_scripting():
            inp = checkpoint_sequential(self.stages, len(self.stages), inp)
        else:
            inp = self.stages(inp)
        return inp

    def forward_head(self, inp, pre_logits: bool = False):
        inp = inp.mean((2, 3), keepdim=True)
        inp = torch.flatten(inp, 1)
        inp = self.drop(inp)
        return inp if pre_logits else self.fc(inp)

    def forward(self, inp):
        inp = self.forward_features(inp)
        inp = self.forward_head(inp)
        return inp


def _tinynet(variant, weights=None, progress=True, **kwargs):
    cfgs = {"small": ([(1, 16, 3, 1, True), (4, 24, 1, 2, True)], [(64, 3)]), "base": ([(1, 16, 4, 1, True), (4, 24, 2, 2, True)], [(64, 4)])}
    model = TinyNet(*cfgs[variant], **kwargs)
    if weights is not None:
        model.load_state_dict(weights.get_state_dict(progress=progress))
    return model


def create_net(weights=None, progress=True, **kwargs):
    return _tinynet('base', weights, progress, **kwargs)


