from typing import Callable, List, Optional

import torch
import torch.nn as nn
import torch.nn.functional as F
from torch import Tensor


def conv3(in_planes, out_planes, stride=1, groups=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=3, stride=stride, padding=1,
                     groups=groups, bias=False)


def conv1(in_planes, out_planes, stride=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=1, stride=stride, bias=False)


class ResidualBlock(nn.Module):
    expansion = 1

    def __init__(self, inplanes, planes, stride=1, downsample: Optional[nn.Module] = None):
        super().__init__()
        self.c1 = conv3(inplanes, planes, stride)
        self.bn1 = nn.BatchNorm2d(planes)
        self.c2 = conv3(planes, planes)
        self.bn2 = nn.BatchNorm2d(planes)
        self.relu1 = nn.ReLU6()
        self.relu2 = nn.ReLU6()
        self.downsample = downsample
        self.stride = stride

    def forward(self, tensor: Tensor) -> Tensor:
        identity = tensor

        out = self.c1(tensor)
        out = self.bn1(out)
        out = self.relu1(out)
        out = self.c2(out)
        out = self.bn2(out)

        if self.downsample is not None:
            identity = self.downsample(tensor)

        out += identity
        out = self.relu2(out)
        return out


def downsample_conv(in_chs, out_chs, stride=1, norm_layer=None):
    norm_layer = norm_layer or nn.BatchNorm2d
    return nn.Sequential(nn.Conv2d(in_chs, out_chs, kernel_size=1, stride=stride, bias=False), norm_layer(out_chs))


def downsample_avg(in_chs, out_chs, stride=1, norm_layer=None):
    norm_layer = norm_layer or nn.BatchNorm2d
    pool = nn.AvgPool2d(2, stride, ceil_mode=True, count_include_pad=False) if stride > 1 else nn.Identity()
    return nn.Sequential(pool, nn.Conv2d(in_chs, out_chs, kernel_size=1, stride=1, bias=False), norm_layer(out_chs))


class SqueezeExpand(nn.Module):
    def __init__(self, inplanes, squeeze_planes, expand1x1_planes, expand3x3_planes):
        super().__init__()
        self.inplanes = inplanes
        self.reduce = nn.Conv2d(inplanes, squeeze_planes, kernel_size=1)
        self.expand_a = nn.Conv2d(squeeze_planes, expand1x1_planes, kernel_size=1)
        self.expand_b = nn.Conv2d(squeeze_planes, expand3x3_planes, kernel_size=3, padding=1)
        self.squeeze_activation = nn.ReLU6()
        self.expand1x1_activation = nn.ReLU6()
        self.expand3x3_activation = nn.ReLU6()

    def forward(self, tensor: Tensor) -> Tensor:
        tensor = self.squeeze_activation(self.reduce(tensor))
        return torch.cat(
            [self.expand1x1_activation(self.expand_a(tensor)), self.expand3x3_activation(self.expand_b(tensor))], 1
        )


class BasicConv2d(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size=3, stride=1, groups=1, act=True):
        super().__init__()
        padding = (kernel_size - 1) // 2 if isinstance(kernel_size, int) else tuple((k - 1) // 2 for k in kernel_size)
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride,
                              padding=padding, groups=groups, bias=False)
        self.bn = nn.BatchNorm2d(out_channels)
        self.act = nn.ReLU6() if act else nn.Identity()

    def forward(self, tensor: Tensor) -> Tensor:
        tensor = self.conv(tensor)
        tensor = self.bn(tensor)
        return self.act(tensor)


class Network(nn.Module):
    def __init__(self, early_cfg, late_cfg, in_chans=3, num_classes=100, drop_rate=0.0, down_type='avg', output_stride=32, **kwargs):
        super().__init__()
        assert output_stride in (8, 16, 32)
        self.num_classes = num_classes
        self.stem = BasicConv2d(in_chans, 8, kernel_size=3, stride=2)
        in_ch = 8
        self.stages = nn.ModuleList()
        for idx, (planes, n, stride) in enumerate(early_cfg):
            blocks = []
            downsample = None
            if stride != 1 or in_ch != planes * ResidualBlock.expansion:
                down_fn = downsample_avg if down_type == "avg" else downsample_conv
                downsample = down_fn(in_ch, planes * ResidualBlock.expansion, stride, nn.BatchNorm2d)
            blocks.append(ResidualBlock(in_ch, planes, stride, downsample))
            in_ch = planes * ResidualBlock.expansion
            for _ in range(1, n):
                blocks.append(ResidualBlock(in_ch, planes))
            self.stages.append(nn.Sequential(*blocks))
        for idx, (sq, e, n) in enumerate(late_cfg, start=len(early_cfg)):
            blocks = []
            if idx > 0:
                blocks.append(nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True))
            for _ in range(n):
                blocks.append(SqueezeExpand(in_ch, sq, e, e))
                in_ch = 2 * e
            self.stages.append(nn.Sequential(*blocks))
        self.drop = nn.Dropout(drop_rate)
        self.fc = nn.Linear(in_ch, num_classes)

    def forward_features(self, tensor):
        tensor = self.stem(tensor)
        for stage in self.stages:
            tensor = stage(tensor)
        return tensor

    def forward_head(self, tensor, pre_logits: bool = False):
        tensor = tensor.mean((2, 3))
        tensor = tensor.flatten(1)
        tensor = self.drop(tensor)
        return tensor if pre_logits else self.fc(tensor)

    def forward(self, tensor):
        tensor = self.forward_features(tensor)
        tensor = self.forward_head(tensor)
        return tensor


def _network(variant, weights=None, progress=True, **kwargs):
    cfgs = {"small": ([(8, 1, 1), (16, 2, 2)], [(24, 96, 1), (32, 128, 3)]), "base": ([(8, 2, 1), (16, 3, 2)], [(24, 96, 2), (32, 128, 4)])}
    model = Network(*cfgs[variant], **kwargs)
    if weights is not None:
        model.load_state_dict(weights.get_state_dict(progress=progress))
    return model


def network_small(weights=None, progress=True, **kwargs):
    return _network('base', weights, progress, **kwargs)


