import torch
from torch import nn
from torch.nn import functional as F
from functools import partial


class SqueezeExpand(nn.Module):
    def __init__(self, inplanes, squeeze_planes, expand1x1_planes, expand3x3_planes):
        super(SqueezeExpand, self).__init__()
        self.inplanes = inplanes
        self.sq = nn.Conv2d(inplanes, squeeze_planes, kernel_size=1)
        self.ex1 = nn.Conv2d(squeeze_planes, expand1x1_planes, kernel_size=1)
        self.ex3 = nn.Conv2d(squeeze_planes, expand3x3_planes, kernel_size=3, padding=1)

    def forward(self, z):
        z = F.silu(self.sq(z), inplace=True)
        return torch.cat(
            [F.silu(self.ex1(z), inplace=True), F.silu(self.ex3(z), inplace=True)], 1
        )


class ConvBNActivation(nn.Sequential):
    def __init__(self, in_channels, out_channels, kernel_size=3, stride=1, groups=1, act=True):
        padding = (kernel_size - 1) // 2 if isinstance(kernel_size, int) else tuple((k - 1) // 2 for k in kernel_size)
        layers = [
            nn.Conv2d(in_channels, out_channels, kernel_size, stride, padding, groups=groups, bias=False),
            nn.BatchNorm2d(out_channels),
        ]
        if act:
            layers.append(nn.SiLU(inplace=True))
        super(ConvBNActivation, self).__init__(*layers)


class ResStage(nn.Module):
    def __init__(self, sq, e, n, in_ch, pool=False):
        super(ResStage, self).__init__()

        blocks = []
        if pool:
            blocks.append(nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True))
        for _ in range(n):
            blocks.append(SqueezeExpand(in_ch, sq, e, e))
            in_ch = 2 * e
        self.blocks = nn.Sequential(*blocks)
        self.out_channels = in_ch

    def forward(self, x):
        return self.blocks(x)


class Model(nn.Module):
    def __init__(self, stage_cfg, in_chans=3, num_classes=100, drop_rate=0.0, norm_layer=None):
        super(Model, self).__init__()
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=0.001)
        self.num_classes = num_classes
        self.stem = ConvBNActivation(in_chans, 8, kernel_size=3, stride=2)
        in_ch = 8
        stages = []
        for idx, (sq, e, n) in enumerate(stage_cfg):
            stage = ResStage(sq, e, n, in_ch, idx > 0)
            stages.append(stage)
            in_ch = stage.out_channels
        self.stages = nn.Sequential(*stages)
        self.conv_head = nn.Conv2d(in_ch, 128, kernel_size=1, bias=False)
        self.act_head = nn.SiLU(inplace=True)
        in_ch = 128
        self.global_pool = nn.AdaptiveAvgPool2d(1)
        self.classifier = nn.Sequential(nn.Flatten(1), nn.Dropout(p=drop_rate), nn.Linear(in_ch, num_classes))

    def forward(self, z):
        torch._assert(z.dim() == 4, f"expected a 4D input, got {z.dim()}D")
        z = self.stem(z)
        z = self.stages(z)
        z = self.conv_head(z)
        z = self.act_head(z)
        z = self.global_pool(z)
        return self.classifier(z)


def _model(variant, weights=None, progress=True, **kwargs):
    cfgs = {"small": [(8, 32, 1), (16, 64, 2), (24, 96, 3), (32, 128, 2)]}
    model = Model(cfgs[variant], **kwargs)
    if weights is not None:
        model.load_state_dict(weights.get_state_dict(progress=progress))
    return model


def model_small(weights=None, progress=True, **kwargs):
    return _model('small', weights, progress, **kwargs)


