import torch
from torch import Tensor, nn
import torch.nn.functional as F
from functools import partial


class Fire(nn.Module):
    def __init__(self, inplanes, squeeze_planes, expand1x1_planes, expand3x3_planes):
        super().__init__()
        self.inplanes = inplanes
        self.sq = nn.Conv2d(inplanes, squeeze_planes, kernel_size=1)
        self.ex1 = nn.Conv2d(squeeze_planes, expand1x1_planes, kernel_size=1)
        self.ex3 = nn.Conv2d(squeeze_planes, expand3x3_planes, kernel_size=3, padding=1)
        self.squeeze_activation = nn.Hardswish(inplace=True)
        self.expand1x1_activation = nn.Hardswish(inplace=True)
        self.expand3x3_activation = nn.Hardswish(inplace=True)

    def forward(self, inp: Tensor) -> Tensor:
        inp = self.squeeze_activation(self.sq(inp))
        return torch.cat(
            [self.expand1x1_activation(self.ex1(inp)), self.expand3x3_activation(self.ex3(inp))], 1
        )


class Stem(nn.Module):
    def __init__(self, in_chs, out_chs, norm_layer=nn.BatchNorm2d):
        super().__init__()
        self.conv = nn.Conv2d(in_chs, out_chs, kernel_size=3, stride=2, padding=1, bias=False)
        self.norm = norm_layer(out_chs)
        self.act = nn.Hardswish(inplace=True)
        self.pool = nn.MaxPool2d(kernel_size=3, stride=2, padding=1)

    def forward(self, x):
        x = self.conv(x)
        x = self.norm(x)
        x = self.act(x)
        x = self.pool(x)
        return x


class NetStage(nn.Module):
    def __init__(self, sq, e, n, in_ch, pool=False):
        super().__init__()

        blocks = []
        if pool:
            blocks.append(nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True))
        for _ in range(n):
            blocks.append(Fire(in_ch, sq, e, e))
            in_ch = 2 * e
        self.layers = nn.Sequential(*blocks)
        self.out_channels = in_ch

    def forward(self, x):
        return self.layers(x)


class Network(nn.Module):
    def __init__(self, stage_cfg, in_chans=3, num_classes=10, drop_rate=0.0, norm_layer: Optional[Callable[..., nn.Module]] = None, output_stride=32, **kwargs):
        super().__init__()
        assert output_stride in (8, 16, 32)
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=1e-5)
        self.num_classes = num_classes
        self.stem = Stem(in_chans, 8, norm_layer=norm_layer)
        in_ch = 8
        stages = []
        for idx, (sq, e, n) in enumerate(stage_cfg):
            stage = NetStage(sq, e, n, in_ch, idx > 0)
            stages.append(stage)
            in_ch = stage.out_channels
        self.stages = nn.ModuleList(stages)
        self.drop = nn.Dropout(drop_rate)
        self.fc = nn.Linear(in_ch, num_classes)

    def forward(self, inp: Tensor) -> Tensor:
        torch._assert(inp.dim() == 4, f"expected a 4D input, got {inp.dim()}D")
        inp = self.stem(inp)
        for stage in self.stages:
            inp = stage(inp)
        inp = inp.mean((-2, -1))
        inp = inp.flatten(1)
        inp = self.drop(inp)
        return self.fc(inp)


