    cfgs = {"small": [(8, 32, 1), (16, 64, 2), (24, 96, 2), (32, 128, 3), (40, 160, 2)], "base": [(8, 32, 2), (16, 64, 3), (24, 96, 3), (32, 128, 4), (40, 160, 3)]}
    return Network(cfgs[variant], **kwargs)


