import torch
import torch.nn as nn
import torch.nn.functional as F
from torch import Tensor
from functools import partial
from collections import OrderedDict


class FireModule(nn.Module):
    def __init__(self, inplanes, squeeze_planes, expand1x1_planes, expand3x3_planes):
        super().__init__()
        self.inplanes = inplanes
        self.squeeze = nn.Conv2d(inplanes, squeeze_planes, kernel_size=1)
        self.expand1x1 = nn.Conv2d(squeeze_planes, expand1x1_planes, kernel_size=1)
        self.expand3x3 = nn.Conv2d(squeeze_planes, expand3x3_planes, kernel_size=3, padding=1)
        self.squeeze_activation = nn.ReLU(inplace=True)
        self.expand1x1_activation = nn.ReLU(inplace=True)
        self.expand3x3_activation = nn.ReLU(inplace=True)

    def forward(self, z: Tensor) -> Tensor:
        z = self.squeeze_activation(self.squeeze(z))
        return torch.cat(
            [self.expand1x1_activation(self.expand1x1(z)), self.expand3x3_activation(self.expand3x3(z))], 1
        )


def conv_bn_relu(in_channels, out_channels, kernel_size=3, stride=1, groups=1, act=True):
    padding = (kernel_size - 1) // 2 if isinstance(kernel_size, int) else tuple((k - 1) // 2 for k in kernel_size)
    layers = [
        nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding,
                  groups=groups, bias=False),
        nn.BatchNorm2d(out_channels),
    ]
    if act:
        layers.append(nn.ReLU(inplace=True))
    return nn.Sequential(*layers)


class InvertedResidual(nn.Module):
    def __init__(self, inp, oup, stride, expand_ratio, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super().__init__()
        self.stride = stride
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d

        hidden_dim = int(round(inp * expand_ratio))
        self.has_skip = self.stride == 1 and inp == oup

        layers = []
        if expand_ratio != 1:
            layers.append(conv_bn_relu(inp, hidden_dim, kernel_size=1))
        layers.append(conv_bn_relu(hidden_dim, hidden_dim, kernel_size=3, stride=stride, groups=hidden_dim))

        layers.append(nn.Conv2d(hidden_dim, oup, 1, 1, 0, bias=False))
        layers.append(norm_layer(oup))
        self.conv = nn.Sequential(*layers)

    def forward(self, z: Tensor) -> Tensor:
        out = self.conv(z)
        if self.has_skip:
            out = out + z
        return out


class Model(nn.Module):
    def __init__(self, conv_cfg, block_cfg, in_chans=3, num_classes=1000, drop_rate=0.0, norm_layer: Optional[Callable[..., nn.Module]] = None, **kwargs):
        super().__init__()
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=1e-3)
        self.num_classes = num_classes
        self.stem = conv_bn_relu(in_chans, 8, kernel_size=3, stride=2)
        in_ch = 8
        self.feature_info = []
        for idx, (sq, e, n) in enumerate(conv_cfg):
            blocks = []
            if idx > 0:
                blocks.append(nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True))
            for _ in range(n):
                blocks.append(FireModule(in_ch, sq, e, e))
                in_ch = 2 * e
            self.add_module(f"layer{idx + 1}", nn.Sequential(*blocks))
            self.feature_info.append(dict(num_chs=in_ch, module=f"layer{idx + 1}"))
        for idx, (t, c, n, stride, se) in enumerate(block_cfg, start=len(conv_cfg)):
            blocks = []
            out_c = c
            for i in range(n):
                blocks.append(InvertedResidual(in_ch, out_c, stride if i == 0 else 1, t))
                in_ch = out_c
            self.add_module(f"layer{idx + 1}", nn.Sequential(*blocks))
            self.feature_info.append(dict(num_chs=in_ch, module=f"layer{idx + 1}"))
        self.num_stages = len(conv_cfg) + len(block_cfg)
        self.num_features = in_ch
        self.global_pool = nn.AdaptiveAvgPool2d((1, 1))
        self.classifier = nn.Sequential(OrderedDict([
            ("flatten", nn.Flatten(1)),
            ("drop", nn.Dropout(p=drop_rate)),
            ("fc", nn.Linear(in_ch, num_classes)),
        ]))

    def forward(self, z: Tensor) -> Tensor:
        z = self.stem(z)
        for i in range(self.num_stages):
            z = getattr(self, f"layer{i + 1}")(z)
        z = self.global_pool(z)
        return self.classifier(z)


def make_model(variant="small", **kwargs):
    cfgs = {"small": ([(8, 32, 2), (16, 64, 2), (24, 96, 3)], [(3, 40, 1, 2, False)])}
    return Model(*cfgs[variant], **kwargs)


