import torch
import torch.nn as nn
import torch.nn.functional as F
from torch import Tensor
from functools import partial


def make_conv3(in_planes, out_planes, stride=1, groups=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=3, stride=stride, padding=1,
                     groups=groups, bias=False)


def make_conv1(in_planes, out_planes, stride=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=1, stride=stride, bias=False)


class ResBlock(nn.Module):
    expansion = 1

    def __init__(self, inplanes, planes, stride=1, downsample: Optional[nn.Module] = None, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super(ResBlock, self).__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.c1 = make_conv3(inplanes, planes, stride)
        self.bn1 = norm_layer(planes)
        self.c2 = make_conv3(planes, planes)
        self.bn2 = norm_layer(planes)
        self.downsample = downsample
        self.stride = stride

    def forward(self, x: Tensor) -> Tensor:
        shortcut_out = x

        out = self.c1(x)
        out = self.bn1(out)
        out = F.relu(out)
        out = self.c2(out)
        out = self.bn2(out)

        if self.downsample is not None:
            shortcut_out = self.downsample(x)

        out += shortcut_out
        out = torch.relu(out)
        return out


def downsample_conv(in_chs, out_chs, stride=1, norm_layer=None):
    if norm_layer is None:
        norm_layer = nn.BatchNorm2d
    return nn.Sequential(nn.Conv2d(in_chs, out_chs, kernel_size=1, stride=stride, bias=False), norm_layer(out_chs))


def downsample_avg(in_chs, out_chs, stride=1, norm_layer=None):
    if norm_layer is None:
        norm_layer = nn.BatchNorm2d
    pool = nn.AvgPool2d(2, stride, ceil_mode=True, count_include_pad=False) if stride > 1 else nn.Identity()
    return nn.Sequential(pool, nn.Conv2d(in_chs, out_chs, kernel_size=1, stride=1, bias=False), norm_layer(out_chs))


class ConvNet(nn.Module):
    def __init__(self, arch, in_chans=3, num_classes=1000, drop_rate=0.0, norm_layer: Optional[Callable[..., nn.Module]] = None, down_type='avg', **kwargs):
        super(ConvNet, self).__init__()
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=1e-3)
        self.num_classes = num_classes
        self.conv_stem = nn.Conv2d(in_chans, 8, kernel_size=3, stride=2, padding=1, bias=False)
        self.bn1 = norm_layer(8)
        self.act1 = nn.ReLU()
        in_ch = 8
        for idx, (planes, n, stride) in enumerate(arch):
            blocks = []
            downsample = None
            if stride != 1 or in_ch != planes * ResBlock.expansion:
                down_fn = downsample_avg if down_type == "avg" else downsample_conv
                downsample = down_fn(in_ch, planes * ResBlock.expansion, stride, norm_layer)
            blocks.append(ResBlock(in_ch, planes, stride, downsample))
            in_ch = planes * ResBlock.expansion
            for _ in range(1, n):
                blocks.append(ResBlock(in_ch, planes))
            self.add_module(f"stage{idx + 1}", nn.Sequential(*blocks))
        self.num_stages = len(arch)
        self.conv_head = nn.Conv2d(in_ch, 128, kernel_size=1, bias=False)
        self.act_head = nn.ReLU()
        in_ch = 128
        self.drop = nn.Identity()
        self.fc = nn.Linear(in_ch, num_classes)

    def forward(self, x: Tensor) -> Tensor:
        x = self.conv_stem(x)
        x = self.bn1(x)
        x = self.act1(x)
        for i in range(self.num_stages):
            x = getattr(self, f"stage{i + 1}")(x)
        x = self.conv_head(x)
        x = self.act_head(x)
        x = F.adaptive_avg_pool2d(x, 1)
        x = torch.flatten(x, 1)
        x = self.drop(x)
        return self.fc(x)


def _convnet(variant, weights=None, progress=True, **kwargs):
    cfgs = {"small": [(8, 1, 1), (16, 3, 2), (32, 1, 2), (64, 3, 2)]}
    model = ConvNet(cfgs[variant], **kwargs)
    if weights is not None:
        model.load_state_dict(weights.get_state_dict(progress=progress))
    return model


def convnet_small(weights=None, progress=True, **kwargs):
    return _convnet('small', weights, progress, **kwargs)


