import torch
import torch.nn as nn
import torch.nn.functional as F
from torch import Tensor
from torchvision.ops import Conv2dNormActivation
from functools import partial


def make_conv3(in_planes, out_planes, stride=1, groups=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=3, stride=stride, padding=1,
                     groups=groups, bias=False)


def make_conv1(in_planes, out_planes, stride=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=1, stride=stride, bias=False)


class BottleneckBlock(nn.Module):
    expansion = 4

    def __init__(self, inplanes, planes, stride=1, shortcut: Optional[nn.Module] = None, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super().__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.c1 = make_conv1(inplanes, planes)
        self.bn_a = norm_layer(planes)
        self.c2 = make_conv3(planes, planes, stride)
        self.bn_b = norm_layer(planes)
        self.c3 = make_conv1(planes, planes * self.expansion)
        self.bn_c = norm_layer(planes * self.expansion)
        self.shortcut = shortcut
        self.stride = stride

    def forward(self, inp: Tensor) -> Tensor:
        skip_val = inp

        h = self.c1(inp)
        h = self.bn_a(h)
        h = torch.relu(h)
        h = self.c2(h)
        h = self.bn_b(h)
        h = torch.relu(h)
        h = self.c3(h)
        h = self.bn_c(h)

        if self.shortcut is not None:
            skip_val = self.shortcut(inp)

        h += skip_val
        h = F.relu(h)
        return h


class Stage(nn.Module):
    def __init__(self, planes, n, stride, in_ch, norm_layer=None):
        super().__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        blocks = []
        downsample = None
        if stride != 1 or in_ch != planes * BottleneckBlock.expansion:
            downsample = nn.Sequential(
                make_conv1(in_ch, planes * BottleneckBlock.expansion, stride),
                norm_layer(planes * BottleneckBlock.expansion),
            )
        blocks.append(BottleneckBlock(in_ch, planes, stride, downsample))
        in_ch = planes * BottleneckBlock.expansion
        for _ in range(1, n):
            blocks.append(BottleneckBlock(in_ch, planes))
        self.blocks = nn.Sequential(*blocks)
        self.out_channels = in_ch

    def forward(self, x):
        return self.blocks(x)


class ClassifierHead(nn.Module):
    def __init__(self, in_features, num_classes, drop_rate=0.0):
        super().__init__()

        self.flatten = nn.Flatten(1)
        self.drop = nn.Dropout(drop_rate)
        self.fc = nn.Linear(in_features, num_classes) if num_classes > 0 else nn.Identity()

    def forward(self, x, pre_logits: bool = False):
        x = x.mean((2, 3), keepdim=True)
        x = self.flatten(x)
        x = self.drop(x)
        return x if pre_logits else self.fc(x)


class Backbone(nn.Module):
    def __init__(self, stage_cfg, in_chans=3, num_classes=1000, drop_rate=0.0, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super().__init__()
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=1e-3)
        self.num_classes = num_classes
        self.stem = Conv2dNormActivation(in_chans, 8, kernel_size=3, stride=2)
        in_ch = 8
        stages = []
        for idx, (planes, n, stride) in enumerate(stage_cfg):
            stage = Stage(planes, n, stride, in_ch)
            stages.append(stage)
            in_ch = stage.out_channels
        self.stages = nn.Sequential(*stages)
        self.head = ClassifierHead(in_ch, num_classes, drop_rate=drop_rate)

    def forward(self, inp: Tensor) -> Tensor:
        torch._assert(inp.dim() == 4, f"expected a 4D input, got {inp.dim()}D")
        inp = self.stem(inp)
        inp = self.stages(inp)
        return self.head(inp)


def _backbone(variant, weights=None, progress=True, **kwargs):
    cfgs = {"small": [(8, 2, 1), (16, 3, 2), (32, 3, 2)]}
    model = Backbone(cfgs[variant], **kwargs)
    if weights is not None:
        model.load_state_dict(weights.get_state_dict(progress=progress))
    return model


def create_net(weights=None, progress=True, **kwargs):
    return _backbone('small', weights, progress, **kwargs)


