from typing import Any, Callable, List, Optional

import torch
from torch import Tensor, nn
import torch.nn.functional as F
from functools import partial
from collections import OrderedDict


def make_conv(in_channels, out_channels, kernel_size=3, stride=1, groups=1, act=True):
    padding = (kernel_size - 1) // 2 if isinstance(kernel_size, int) else tuple((k - 1) // 2 for k in kernel_size)
    layers = [
        nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding,
                  groups=groups, bias=False),
        nn.BatchNorm2d(out_channels),
    ]
    if act:
        layers.append(nn.Hardswish(inplace=True))
    return nn.Sequential(*layers)


class SEBlock(nn.Module):
    def __init__(self, channels, squeeze_channels):
        super(SEBlock, self).__init__()
        self.avgpool = nn.AdaptiveAvgPool2d(1)
        self.fc1 = nn.Conv2d(channels, squeeze_channels, 1)
        self.fc2 = nn.Conv2d(squeeze_channels, channels, 1)
        self.activation = nn.ReLU()
        self.scale_activation = nn.Hardsigmoid()

    def forward(self, inp: Tensor) -> Tensor:
        scale = self.avgpool(inp)
        scale = self.fc1(scale)
        scale = self.activation(scale)
        scale = self.fc2(scale)
        scale = self.scale_activation(scale)
        return scale * inp


class MBConv(nn.Module):
    def __init__(self, inp, oup, stride, expand_ratio, use_se=False, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super(MBConv, self).__init__()
        self.stride = stride
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d

        hidden_dim = int(round(inp * expand_ratio))
        self.residual = self.stride == 1 and inp == oup

        layers = []
        if expand_ratio != 1:
            layers.append(make_conv(inp, hidden_dim, kernel_size=1))
        layers.append(make_conv(hidden_dim, hidden_dim, kernel_size=5, stride=stride, groups=hidden_dim))
        if use_se:
            layers.append(SEBlock(hidden_dim, max(1, hidden_dim // 4)))
        layers.append(nn.Conv2d(hidden_dim, oup, 1, 1, 0, bias=False))
        layers.append(norm_layer(oup))
        self.conv = nn.Sequential(*layers)

    def forward(self, inp: Tensor) -> Tensor:
        out = self.conv(inp)
        if self.residual:
            out = out + inp
        return out


class ResStage(nn.Module):
    def __init__(self, t, c, n, stride, se, in_ch):
        super(ResStage, self).__init__()

        blocks = []
        out_c = c
        for i in range(n):
            blocks.append(MBConv(in_ch, out_c, stride if i == 0 else 1, t, use_se=se))
            in_ch = out_c
        self.blocks = nn.Sequential(*blocks)
        self.out_channels = in_ch

    def forward(self, x):
        return self.blocks(x)


class Network(nn.Module):
    def __init__(self, cfg, in_chans=3, num_classes=10, drop_rate=0.0, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super(Network, self).__init__()
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=1e-3)
        self.num_classes = num_classes
        self.stem = make_conv(in_chans, 8, kernel_size=3, stride=2)
        in_ch = 8
        stages = []
        for idx, (t, c, n, stride, se) in enumerate(cfg):
            stage = ResStage(t, c, n, stride, se, in_ch)
            stages.append(stage)
            in_ch = stage.out_channels
        self.stages = nn.ModuleList(stages)
        self.classifier = nn.Sequential(OrderedDict([
            ("flatten", nn.Flatten(1)),
            ("drop", nn.Dropout(p=drop_rate)),
            ("fc", nn.Linear(in_ch, num_classes)),
        ]))

    def forward(self, inp: Tensor) -> Tensor:
        inp = self.stem(inp)
        for stage in self.stages:
            inp = stage(inp)
        inp = F.adaptive_avg_pool2d(inp, 1)
        return self.classifier(inp)


def _network(variant, weights=None, progress=True, **kwargs):
    cfgs = {"small": [(1, 16, 1, 1, False), (4, 24, 1, 2, True), (4, 32, 3, 2, True), (3, 40, 3, 2, False), (6, 48, 2, 2, False)], "base": [(1, 16, 2, 1, False), (4, 24, 2, 2, True), (4, 32, 4, 2, True), (3, 40, 4, 2, False), (6, 48, 3, 2, False)]}
    model = Network(cfgs[variant], **kwargs)
    if weights is not None:
        model.load_state_dict(weights.get_state_dict(progress=progress))
    return model


def create_net(weights=None, progress=True, **kwargs):
    return _network('base', weights, progress, **kwargs)


