import torch
from torch import nn
from torch.nn import functional as F
from functools import partial


class FireModule(nn.Module):
    def __init__(self, inplanes, squeeze_planes, expand1x1_planes, expand3x3_planes):
        super().__init__()
        self.inplanes = inplanes
        self.squeeze = nn.Conv2d(inplanes, squeeze_planes, kernel_size=1)
        self.expand1x1 = nn.Conv2d(squeeze_planes, expand1x1_planes, kernel_size=1)
        self.expand3x3 = nn.Conv2d(squeeze_planes, expand3x3_planes, kernel_size=3, padding=1)
        self.act = nn.ReLU6(inplace=True)

    def forward(self, tensor):
        tensor = self.act(self.squeeze(tensor))
        return torch.cat(
            [self.act(self.expand1x1(tensor)), self.act(self.expand3x3(tensor))], 1
        )


class ConvBNReLU(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size=3, stride=1, groups=1, act=True):
        super().__init__()
        padding = (kernel_size - 1) // 2 if isinstance(kernel_size, int) else tuple((k - 1) // 2 for k in kernel_size)
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride,
                              padding=padding, groups=groups, bias=False)
        self.bn = nn.BatchNorm2d(out_channels)
        self.act = nn.ReLU6(inplace=True) if act else nn.Identity()

    def forward(self, tensor):
        tensor = self.conv(tensor)
        tensor = self.bn(tensor)
        return self.act(tensor)


class ConvNet(nn.Module):
    def __init__(self, stage_cfg, in_chans=3, num_classes=10, drop_rate=0.0, norm_layer=None, output_stride=32):
        super().__init__()
        assert output_stride in (8, 16, 32)
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=0.001)
        self.num_classes = num_classes
        self.stem = ConvBNReLU(in_chans, 16, kernel_size=3, stride=2)
        in_ch = 16
        for idx, (sq, e, n) in enumerate(stage_cfg):
            blocks = []
            if idx > 0:
                blocks.append(nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True))
            for _ in range(n):
                blocks.append(FireModule(in_ch, sq, e, e))
                in_ch = 2 * e
            self.add_module(f"stage{idx + 1}", nn.Sequential(*blocks))
        self.num_stages = len(stage_cfg)
        self.drop = nn.Identity()
        self.fc = nn.Linear(in_ch, num_classes)

    def forward_features(self, tensor):
        tensor = self.stem(tensor)
        for i in range(self.num_stages):
            tensor = getattr(self, f"stage{i + 1}")(tensor)
        return tensor

    def forward_head(self, tensor, pre_logits: bool = False):
        tensor = F.adaptive_avg_pool2d(tensor, 1)
        tensor = torch.flatten(tensor, 1)
        tensor = self.drop(tensor)
        return tensor if pre_logits else self.fc(tensor)

    def forward(self, tensor):
        tensor = self.forward_features(tensor)
        tensor = self.forward_head(tensor)
        return tensor


def build_model(variant="small", **kwargs):
    cfgs = {"small": [(8, 32, 1), (16, 64, 2), (24, 96, 3), (32, 128, 2)], "base": [(8, 32, 2), (16, 64, 3), (24, 96, 4), (32, 128, 3)]}
    return ConvNet(cfgs[variant], **kwargs)


