from typing import Callable, List, Optional

import torch
import torch.nn as nn
import torch.nn.functional as F
from torch import Tensor
from functools import partial


def conv3x3(in_planes, out_planes, stride=1, groups=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=3, stride=stride, padding=1,
                     groups=groups, bias=False)


def conv1x1(in_planes, out_planes, stride=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=1, stride=stride, bias=False)


class Bottleneck(nn.Module):
    expansion = 4

    def __init__(self, inplanes, planes, stride=1, shortcut: Optional[nn.Module] = None, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super().__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.c1 = conv1x1(inplanes, planes)
        self.bn1 = norm_layer(planes)
        self.c2 = conv3x3(planes, planes, stride)
        self.bn2 = norm_layer(planes)
        self.c3 = conv1x1(planes, planes * self.expansion)
        self.bn3 = norm_layer(planes * self.expansion)
        self.relu1 = nn.ReLU(inplace=True)
        self.relu2 = nn.ReLU(inplace=True)
        self.relu3 = nn.ReLU(inplace=True)
        self.shortcut = shortcut
        self.stride = stride

    def forward(self, tensor: Tensor) -> Tensor:
        shortcut_out = tensor

        h = self.c1(tensor)
        h = self.bn1(h)
        h = self.relu1(h)
        h = self.c2(h)
        h = self.bn2(h)
        h = self.relu2(h)
        h = self.c3(h)
        h = self.bn3(h)

        if self.shortcut is not None:
            shortcut_out = self.shortcut(tensor)

        h = h + shortcut_out
        h = self.relu3(h)
        return h


def make_conv3(in_planes, out_planes, stride=1, groups=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=3, stride=stride, padding=1,
                     groups=groups, bias=False)


def make_conv1(in_planes, out_planes, stride=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=1, stride=stride, bias=False)


class SkipBlock(nn.Module):
    expansion = 1

    def __init__(self, inplanes, planes, stride=1, downsample: Optional[nn.Module] = None, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super().__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.conv_a = make_conv3(inplanes, planes, stride)
        self.bn_a = norm_layer(planes)
        self.conv_b = make_conv3(planes, planes)
        self.bn_b = norm_layer(planes)
        self.relu1 = nn.ReLU(inplace=True)
        self.relu2 = nn.ReLU(inplace=True)
        self.downsample = downsample
        self.stride = stride

    def forward(self, tensor: Tensor) -> Tensor:
        shortcut_out = tensor

        y = self.conv_a(tensor)
        y = self.bn_a(y)
        y = self.relu1(y)
        y = self.conv_b(y)
        y = self.bn_b(y)

        if self.downsample is not None:
            shortcut_out = self.downsample(tensor)

        y += shortcut_out
        y = self.relu2(y)
        return y


def downsample_conv(in_chs, out_chs, stride=1, norm_layer=None):
    if norm_layer is None:
        norm_layer = nn.BatchNorm2d
    return nn.Sequential(nn.Conv2d(in_chs, out_chs, kernel_size=1, stride=stride, bias=False), norm_layer(out_chs))


def downsample_avg(in_chs, out_chs, stride=1, norm_layer=None):
    if norm_layer is None:
        norm_layer = nn.BatchNorm2d
    pool = nn.AvgPool2d(2, stride, ceil_mode=True, count_include_pad=False) if stride > 1 else nn.Identity()
    return nn.Sequential(pool, nn.Conv2d(in_chs, out_chs, kernel_size=1, stride=1, bias=False), norm_layer(out_chs))


class Fire(nn.Module):
    def __init__(self, inplanes, squeeze_planes, expand1x1_planes, expand3x3_planes):
        super().__init__()
        self.inplanes = inplanes
        self.sq = nn.Conv2d(inplanes, squeeze_planes, kernel_size=1)
        self.ex1 = nn.Conv2d(squeeze_planes, expand1x1_planes, kernel_size=1)
        self.ex3 = nn.Conv2d(squeeze_planes, expand3x3_planes, kernel_size=3, padding=1)
        self.squeeze_activation = nn.ReLU(inplace=True)
        self.expand1x1_activation = nn.ReLU(inplace=True)
        self.expand3x3_activation = nn.ReLU(inplace=True)

    def forward(self, tensor: Tensor) -> Tensor:
        tensor = self.squeeze_activation(self.sq(tensor))
        return torch.cat(
            [self.expand1x1_activation(self.ex1(tensor)), self.expand3x3_activation(self.ex3(tensor))], 1
        )


class ConvBNAct(nn.Sequential):
    def __init__(self, in_channels, out_channels, kernel_size=3, stride=1, groups=1, act=True):
        padding = (kernel_size - 1) // 2 if isinstance(kernel_size, int) else tuple((k - 1) // 2 for k in kernel_size)
        layers = [
            nn.Conv2d(in_channels, out_channels, kernel_size, stride, padding, groups=groups, bias=False),
            nn.BatchNorm2d(out_channels),
        ]
        if act:
            layers.append(nn.ReLU(inplace=True))
        super().__init__(*layers)


class Model(nn.Module):
    def __init__(self, block, cfg_a, cfg_b, in_chans=3, num_classes=1000, drop_rate=0.0, norm_layer: Optional[Callable[..., nn.Module]] = None, down_type='avg', output_stride=32):
        super().__init__()
        assert output_stride in (8, 16, 32)
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=0.001)
        self.num_classes = num_classes
        self.stem = ConvBNAct(in_chans, 16, kernel_size=3, stride=2)
        in_ch = 16
        self.feature_info = []
        self.stages = nn.ModuleList()
        for idx, (planes, n, stride) in enumerate(cfg_a):
            blocks = []
            downsample = None
            if stride != 1 or in_ch != planes * block.expansion:
                down_fn = downsample_avg if down_type == "avg" else downsample_conv
                downsample = down_fn(in_ch, planes * block.expansion, stride, norm_layer)
            blocks.append(block(in_ch, planes, stride, downsample))
            in_ch = planes * block.expansion
            for _ in range(1, n):
                blocks.append(block(in_ch, planes))
            self.stages.append(nn.Sequential(*blocks))
            self.feature_info.append(dict(num_chs=in_ch, module=f"stages.{idx}"))
        for idx, (sq, e, n) in enumerate(cfg_b, start=len(cfg_a)):
            blocks = []
            if idx > 0:
                blocks.append(nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True))
            for _ in range(n):
                blocks.append(Fire(in_ch, sq, e, e))
                in_ch = 2 * e
            self.stages.append(nn.Sequential(*blocks))
            self.feature_info.append(dict(num_chs=in_ch, module=f"stages.{idx}"))
        self.num_features = in_ch
        self.conv_head = nn.Conv2d(in_ch, 128, kernel_size=1, bias=False)
        self.act_head = nn.ReLU(inplace=True)
        in_ch = 128
        self.drop = nn.Identity()
        self.fc = nn.Linear(in_ch, num_classes)

    def forward_features(self, tensor):
        tensor = self.stem(tensor)
        for stage in self.stages:
            tensor = stage(tensor)
        tensor = self.conv_head(tensor)
        tensor = self.act_head(tensor)
        return tensor

    def forward_head(self, tensor, pre_logits: bool = False):
        tensor = tensor.mean((2, 3))
        tensor = tensor.flatten(1)
        tensor = self.drop(tensor)
        return tensor if pre_logits else self.fc(tensor)

    def forward(self, tensor):
        tensor = self.forward_features(tensor)
        tensor = self.forward_head(tensor)
        return tensor


def _model(variant, weights=None, progress=True, **kwargs):
    cfgs = {"small": ([(8, 3, 1), (16, 3, 2)], [(24, 96, 1), (32, 128, 3), (40, 160, 2)]), "base": ([(8, 4, 1), (16, 4, 2)], [(24, 96, 2), (32, 128, 4), (40, 160, 3)])}
    model = Model(Bottleneck, *cfgs[variant], **kwargs)
    if weights is not None:
        model.load_state_dict(weights.get_state_dict(progress=progress))
    return model


def model_tiny(weights=None, progress=True, **kwargs):
    return _model('base', weights, progress, **kwargs)


