import torch
from torch import Tensor, nn
import torch.nn.functional as F
from functools import partial


class ConvBNAct(nn.Sequential):
    def __init__(self, in_channels, out_channels, kernel_size=3, stride=1, groups=1, act=True):
        padding = (kernel_size - 1) // 2 if isinstance(kernel_size, int) else tuple((k - 1) // 2 for k in kernel_size)
        layers = [
            nn.Conv2d(in_channels, out_channels, kernel_size, stride, padding, groups=groups, bias=False),
            nn.BatchNorm2d(out_channels),
        ]
        if act:
            layers.append(nn.ReLU())
        super().__init__(*layers)


class SELayer(nn.Module):
    def __init__(self, channels, squeeze_channels):
        super().__init__()
        self.avgpool = nn.AdaptiveAvgPool2d(1)
        self.fc1 = nn.Conv2d(channels, squeeze_channels, 1)
        self.fc2 = nn.Conv2d(squeeze_channels, channels, 1)
        self.activation = nn.ReLU()
        self.scale_activation = nn.Sigmoid()

    def forward(self, x: Tensor) -> Tensor:
        scale = self.avgpool(x)
        scale = self.fc1(scale)
        scale = self.activation(scale)
        scale = self.fc2(scale)
        scale = self.scale_activation(scale)
        return scale * x


class MBConv(nn.Module):
    def __init__(self, inp, oup, stride, expand_ratio, use_se=False, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super().__init__()
        self.stride = stride
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d

        hidden_dim = int(round(inp * expand_ratio))
        self.use_residual = self.stride == 1 and inp == oup

        layers = []
        if expand_ratio != 1:
            layers.append(ConvBNAct(inp, hidden_dim, kernel_size=1))
        layers.append(ConvBNAct(hidden_dim, hidden_dim, kernel_size=5, stride=stride, groups=hidden_dim))
        if use_se:
            layers.append(SELayer(hidden_dim, max(1, hidden_dim // 4)))
        layers.append(nn.Conv2d(hidden_dim, oup, 1, 1, 0, bias=False))
        layers.append(norm_layer(oup))
        self.conv = nn.Sequential(*layers)

    def forward(self, x: Tensor) -> Tensor:
        if self.use_residual:
            return x + self.conv(x)
        return self.conv(x)


class SqueezeExpand(nn.Module):
    def __init__(self, inplanes, squeeze_planes, expand1x1_planes, expand3x3_planes):
        super().__init__()
        self.inplanes = inplanes
        self.sq = nn.Conv2d(inplanes, squeeze_planes, kernel_size=1)
        self.ex1 = nn.Conv2d(squeeze_planes, expand1x1_planes, kernel_size=1)
        self.ex3 = nn.Conv2d(squeeze_planes, expand3x3_planes, kernel_size=3, padding=1)

    def forward(self, x: Tensor) -> Tensor:
        x = F.relu(self.sq(x))
        return torch.cat(
            [F.relu(self.ex1(x)), F.relu(self.ex3(x))], 1
        )


def make_divisible(v, divisor=8, min_value=None):
    if min_value is None:
        min_value = divisor
    new_v = max(min_value, int(v + divisor / 2) // divisor * divisor)
    if new_v < 0.9 * v:
        new_v += divisor
    return new_v


class Model(nn.Module):
    def __init__(self, cfg_a, cfg_b, in_chans=3, num_classes=100, drop_rate=0.0, width_mult=1.0, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super().__init__()
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=1e-5)
        self.num_classes = num_classes
        self.stem = ConvBNAct(in_chans, 8, kernel_size=3, stride=2)
        in_ch = 8
        for idx, (t, c, n, stride, se) in enumerate(cfg_a):
            blocks = []
            out_c = make_divisible(c * width_mult, 8)
            for i in range(n):
                blocks.append(MBConv(in_ch, out_c, stride if i == 0 else 1, t, use_se=se))
                in_ch = out_c
            self.add_module(f"stage{idx + 1}", nn.Sequential(*blocks))
        for idx, (sq, e, n) in enumerate(cfg_b, start=len(cfg_a)):
            blocks = []
            if idx > 0:
                blocks.append(nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True))
            for _ in range(n):
                blocks.append(SqueezeExpand(in_ch, sq, e, e))
                in_ch = 2 * e
            self.add_module(f"stage{idx + 1}", nn.Sequential(*blocks))
        self.num_stages = len(cfg_a) + len(cfg_b)
        self.conv_head = nn.Conv2d(in_ch, 64, kernel_size=1, bias=False)
        self.act_head = nn.ReLU()
        in_ch = 64
        self.global_pool = nn.AdaptiveAvgPool2d((1, 1))
        self.classifier = nn.Sequential(nn.Flatten(1), nn.Dropout(p=drop_rate), nn.Linear(in_ch, num_classes))

    def forward(self, x: Tensor) -> Tensor:
        x = self.stem(x)
        for i in range(self.num_stages):
            x = getattr(self, f"stage{i + 1}")(x)
        x = self.conv_head(x)
        x = self.act_head(x)
        x = self.global_pool(x)
        return self.classifier(x)


def _model(variant, weights=None, progress=True, **kwargs):
    cfgs = {"small": ([(1, 16, 3, 1, False), (4, 24, 3, 2, True), (4, 32, 2, 2, False)], [(32, 128, 2), (40, 160, 2)])}
    model = Model(*cfgs[variant], **kwargs)
    if weights is not None:
        model.load_state_dict(weights.get_state_dict(progress=progress))
    return model


def model_tiny(weights=None, progress=True, **kwargs):
    return _model('small', weights, progress, **kwargs)


