import torch
import torch.nn as nn
import torch.nn.functional as F
from torch import Tensor
from collections import OrderedDict


class BasicConv2d(nn.Module):
    def __init__(self, in_channels, out_channels, **kwargs):
        super().__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, bias=False, **kwargs)
        self.bn = nn.BatchNorm2d(out_channels)
        self.act = nn.ReLU6(inplace=True)

    def forward(self, x: Tensor) -> Tensor:
        x = self.conv(x)
        x = self.bn(x)
        return self.act(x)


class InvertedResidual(nn.Module):
    def __init__(self, inp, oup, stride, expand_ratio, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super().__init__()
        self.stride = stride
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d

        hidden_dim = int(round(inp * expand_ratio))
        self.use_residual = self.stride == 1 and inp == oup

        layers = []
        if expand_ratio != 1:
            layers.append(BasicConv2d(inp, hidden_dim, kernel_size=1))
        layers.append(BasicConv2d(hidden_dim, hidden_dim, kernel_size=3, stride=stride, padding=1, groups=hidden_dim))

        layers.append(nn.Conv2d(hidden_dim, oup, 1, 1, 0, bias=False))
        layers.append(norm_layer(oup))
        self.conv = nn.Sequential(*layers)

    def forward(self, x: Tensor) -> Tensor:
        if self.use_residual:
            return x + self.conv(x)
        return self.conv(x)


def conv3x3(in_planes, out_planes, stride=1, groups=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=3, stride=stride, padding=1,
                     groups=groups, bias=False)


def conv1x1(in_planes, out_planes, stride=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=1, stride=stride, bias=False)


class ResBottleneck(nn.Module):
    expansion = 4

    def __init__(self, inplanes, planes, stride=1, proj: Optional[nn.Module] = None, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super().__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.conv_a = conv1x1(inplanes, planes)
        self.bn_a = norm_layer(planes)
        self.conv_b = conv3x3(planes, planes, stride)
        self.bn_b = norm_layer(planes)
        self.conv_c = conv1x1(planes, planes * self.expansion)
        self.bn_c = norm_layer(planes * self.expansion)
        self.relu1 = nn.ReLU6(inplace=True)
        self.relu2 = nn.ReLU6(inplace=True)
        self.relu3 = nn.ReLU6(inplace=True)
        self.proj = proj
        self.stride = stride

    def forward(self, x: Tensor) -> Tensor:
        skip_val = x

        h = self.conv_a(x)
        h = self.bn_a(h)
        h = self.relu1(h)
        h = self.conv_b(h)
        h = self.bn_b(h)
        h = self.relu2(h)
        h = self.conv_c(h)
        h = self.bn_c(h)

        if self.proj is not None:
            skip_val = self.proj(x)

        h += skip_val
        h = self.relu3(h)
        return h


def _round_channels(v, divisor=8, min_value=None):
    if min_value is None:
        min_value = divisor
    new_v = max(min_value, int(v + divisor / 2) // divisor * divisor)
    if new_v < 0.9 * v:
        new_v += divisor
    return new_v


class ConvNet(nn.Module):
    def __init__(self, stem_stages, main_stages, in_chans=3, num_classes=1000, drop_rate=0.0, width_mult=1.0, norm_layer: Optional[Callable[..., nn.Module]] = None, output_stride=32, **kwargs):
        super().__init__()
        assert output_stride in (8, 16, 32)
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.num_classes = num_classes
        self.stem = BasicConv2d(in_chans, 16, kernel_size=3, stride=2, padding=1)
        in_ch = 16
        stages = OrderedDict()
        for idx, (t, c, n, stride, se) in enumerate(stem_stages):
            blocks = []
            out_c = _round_channels(c * width_mult, 8)
            for i in range(n):
                blocks.append(InvertedResidual(in_ch, out_c, stride if i == 0 else 1, t))
                in_ch = out_c
            stages[f"stage{idx + 1}"] = nn.Sequential(*blocks)
        for idx, (planes, n, stride) in enumerate(main_stages, start=len(stem_stages)):
            blocks = []
            downsample = None
            if stride != 1 or in_ch != planes * ResBottleneck.expansion:
                downsample = nn.Sequential(
                    conv1x1(in_ch, planes * ResBottleneck.expansion, stride),
                    norm_layer(planes * ResBottleneck.expansion),
                )
            blocks.append(ResBottleneck(in_ch, planes, stride, downsample))
            in_ch = planes * ResBottleneck.expansion
            for _ in range(1, n):
                blocks.append(ResBottleneck(in_ch, planes))
            stages[f"stage{idx + 1}"] = nn.Sequential(*blocks)
        self.stages = nn.Sequential(stages)
        self.drop = nn.Dropout(drop_rate)
        self.fc = nn.Linear(in_ch, num_classes)

    def forward(self, x: Tensor) -> Tensor:
        x = self.stem(x)
        x = self.stages(x)
        x = x.mean((-2, -1), keepdim=True)
        x = x.flatten(1)
        x = self.drop(x)
        return self.fc(x)


def convnet_small(variant="small", **kwargs):
    cfgs = {"small": ([(1, 16, 1, 1, False), (4, 24, 3, 2, False), (3, 32, 1, 2, False)], [(64, 1, 2)]), "base": ([(1, 16, 2, 1, False), (4, 24, 4, 2, False), (3, 32, 2, 2, False)], [(64, 2, 2)])}
    return ConvNet(*cfgs[variant], **kwargs)


