from typing import Any, Callable, List, Optional

import torch
from torch import Tensor, nn
import torch.nn.functional as F


def conv3x3(in_planes, out_planes, stride=1, groups=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=3, stride=stride, padding=1,
                     groups=groups, bias=False)


def conv1x1(in_planes, out_planes, stride=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=1, stride=stride, bias=False)


class ResBottleneck(nn.Module):
    expansion = 4

    def __init__(self, inplanes, planes, stride=1, proj: Optional[nn.Module] = None, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super().__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.conv_a = conv1x1(inplanes, planes)
        self.bn1 = norm_layer(planes)
        self.conv_b = conv3x3(planes, planes, stride)
        self.bn2 = norm_layer(planes)
        self.conv_c = conv1x1(planes, planes * self.expansion)
        self.bn3 = norm_layer(planes * self.expansion)
        self.relu1 = nn.ReLU()
        self.relu2 = nn.ReLU()
        self.relu3 = nn.ReLU()
        self.proj = proj
        self.stride = stride

    def forward(self, tensor: Tensor) -> Tensor:
        shortcut_out = tensor

        h = self.conv_a(tensor)
        h = self.bn1(h)
        h = self.relu1(h)
        h = self.conv_b(h)
        h = self.bn2(h)
        h = self.relu2(h)
        h = self.conv_c(h)
        h = self.bn3(h)

        if self.proj is not None:
            shortcut_out = self.proj(tensor)

        h = h + shortcut_out
        h = self.relu3(h)
        return h


class FireModule(nn.Module):
    def __init__(self, inplanes, squeeze_planes, expand1x1_planes, expand3x3_planes):
        super().__init__()
        self.inplanes = inplanes
        self.sq = nn.Conv2d(inplanes, squeeze_planes, kernel_size=1)
        self.ex1 = nn.Conv2d(squeeze_planes, expand1x1_planes, kernel_size=1)
        self.ex3 = nn.Conv2d(squeeze_planes, expand3x3_planes, kernel_size=3, padding=1)
        self.squeeze_activation = nn.ReLU()
        self.expand1x1_activation = nn.ReLU()
        self.expand3x3_activation = nn.ReLU()

    def forward(self, tensor: Tensor) -> Tensor:
        tensor = self.squeeze_activation(self.sq(tensor))
        return torch.cat(
            [self.expand1x1_activation(self.ex1(tensor)), self.expand3x3_activation(self.ex3(tensor))], 1
        )


class BasicConv2d(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size=3, stride=1, groups=1, act=True):
        super().__init__()
        padding = (kernel_size - 1) // 2 if isinstance(kernel_size, int) else tuple((k - 1) // 2 for k in kernel_size)
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride,
                              padding=padding, groups=groups, bias=False)
        self.bn = nn.BatchNorm2d(out_channels)
        self.use_act = act

    def forward(self, tensor: Tensor) -> Tensor:
        tensor = self.conv(tensor)
        tensor = self.bn(tensor)
        if not self.use_act:
            return tensor
        return F.relu(tensor)


class ClassifierHead(nn.Module):
    def __init__(self, in_features, num_classes, drop_rate=0.0):
        super().__init__()
        self.global_pool = nn.AdaptiveAvgPool2d(1)
        self.flatten = nn.Flatten(1)
        self.drop = nn.Dropout(drop_rate)
        self.fc = nn.Linear(in_features, num_classes) if num_classes > 0 else nn.Identity()

    def forward(self, x, pre_logits: bool = False):
        x = self.global_pool(x)
        x = self.flatten(x)
        x = self.drop(x)
        return x if pre_logits else self.fc(x)


class ConvNet(nn.Module):
    def __init__(self, stem_stages, main_stages, in_chans=3, num_classes=1000, drop_rate=0.0, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super().__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.num_classes = num_classes
        self.stem = BasicConv2d(in_chans, 16, kernel_size=3, stride=2)
        in_ch = 16
        for idx, (planes, n, stride) in enumerate(stem_stages):
            blocks = []
            downsample = None
            if stride != 1 or in_ch != planes * ResBottleneck.expansion:
                downsample = nn.Sequential(
                    conv1x1(in_ch, planes * ResBottleneck.expansion, stride),
                    norm_layer(planes * ResBottleneck.expansion),
                )
            blocks.append(ResBottleneck(in_ch, planes, stride, downsample))
            in_ch = planes * ResBottleneck.expansion
            for _ in range(1, n):
                blocks.append(ResBottleneck(in_ch, planes))
            self.add_module(f"layer{idx + 1}", nn.Sequential(*blocks))
        for idx, (sq, e, n) in enumerate(main_stages, start=len(stem_stages)):
            blocks = []
            if idx > 0:
                blocks.append(nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True))
            for _ in range(n):
                blocks.append(FireModule(in_ch, sq, e, e))
                in_ch = 2 * e
            self.add_module(f"layer{idx + 1}", nn.Sequential(*blocks))
        self.num_stages = len(stem_stages) + len(main_stages)
        self.head = ClassifierHead(in_ch, num_classes, drop_rate=drop_rate)

    def forward_features(self, tensor):
        tensor = self.stem(tensor)
        for i in range(self.num_stages):
            tensor = getattr(self, f"layer{i + 1}")(tensor)
        return tensor

    def forward_head(self, tensor, pre_logits: bool = False):
        return self.head(tensor, pre_logits=pre_logits)

    def forward(self, tensor):
        tensor = self.forward_features(tensor)
        tensor = self.forward_head(tensor)
        return tensor


def _convnet(variant, weights=None, progress=True, **kwargs):
    cfgs = {"small": ([(8, 1, 1), (16, 3, 2)], [(24, 96, 1), (32, 128, 1)])}
    model = ConvNet(*cfgs[variant], **kwargs)
    if weights is not None:
        model.load_state_dict(weights.get_state_dict(progress=progress))
    return model


def convnet_small(weights=None, progress=True, **kwargs):
    return _convnet('small', weights, progress, **kwargs)


