from typing import Any, Callable, List, Optional

import torch
from torch import Tensor, nn
import torch.nn.functional as F


def make_conv3(in_planes, out_planes, stride=1, groups=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=3, stride=stride, padding=1,
                     groups=groups, bias=False)


def make_conv1(in_planes, out_planes, stride=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=1, stride=stride, bias=False)


class ResBlock(nn.Module):
    expansion = 1

    def __init__(self, inplanes, planes, stride=1, downsample: Optional[nn.Module] = None, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super().__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.c1 = make_conv3(inplanes, planes, stride)
        self.bn1 = norm_layer(planes)
        self.c2 = make_conv3(planes, planes)
        self.bn2 = norm_layer(planes)
        self.downsample = downsample
        self.stride = stride

    def forward(self, inp: Tensor) -> Tensor:
        skip_val = inp

        out = self.c1(inp)
        out = self.bn1(out)
        out = F.relu(out, inplace=True)
        out = self.c2(out)
        out = self.bn2(out)

        if self.downsample is not None:
            skip_val = self.downsample(inp)

        out += skip_val
        out = F.relu(out, inplace=True)
        return out


def conv3x3(in_planes, out_planes, stride=1, groups=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=3, stride=stride, padding=1,
                     groups=groups, bias=False)


def conv1x1(in_planes, out_planes, stride=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=1, stride=stride, bias=False)


class BottleneckBlock(nn.Module):
    expansion = 4

    def __init__(self, inplanes, planes, stride=1, proj: Optional[nn.Module] = None, norm_layer: Optional[Callable[..., nn.Module]] = None):
        super().__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.conv_a = conv1x1(inplanes, planes)
        self.bn_a = norm_layer(planes)
        self.conv_b = conv3x3(planes, planes, stride)
        self.bn_b = norm_layer(planes)
        self.conv_c = conv1x1(planes, planes * self.expansion)
        self.bn_c = norm_layer(planes * self.expansion)
        self.proj = proj
        self.stride = stride

    def forward(self, inp: Tensor) -> Tensor:
        skip_val = inp

        out = self.conv_a(inp)
        out = self.bn_a(out)
        out = F.relu(out, inplace=True)
        out = self.conv_b(out)
        out = self.bn_b(out)
        out = torch.relu(out)
        out = self.conv_c(out)
        out = self.bn_c(out)

        if self.proj is not None:
            skip_val = self.proj(inp)

        out = out + skip_val
        out = F.relu(out, inplace=True)
        return out


def downsample_conv(in_chs, out_chs, stride=1, norm_layer=None):
    if norm_layer is None:
        norm_layer = nn.BatchNorm2d
    return nn.Sequential(nn.Conv2d(in_chs, out_chs, kernel_size=1, stride=stride, bias=False), norm_layer(out_chs))


def downsample_avg(in_chs, out_chs, stride=1, norm_layer=None):
    if norm_layer is None:
        norm_layer = nn.BatchNorm2d
    pool = nn.AvgPool2d(2, stride, ceil_mode=True, count_include_pad=False) if stride > 1 else nn.Identity()
    return nn.Sequential(pool, nn.Conv2d(in_chs, out_chs, kernel_size=1, stride=1, bias=False), norm_layer(out_chs))


class Head(nn.Module):
    def __init__(self, in_features, num_classes, drop_rate=0.0):
        super().__init__()
        self.global_pool = nn.AdaptiveAvgPool2d(1)
        self.flatten = nn.Flatten(1)
        self.drop = nn.Dropout(drop_rate)
        self.fc = nn.Linear(in_features, num_classes) if num_classes > 0 else nn.Identity()

    def forward(self, x, pre_logits: bool = False):
        x = self.global_pool(x)
        x = self.flatten(x)
        x = self.drop(x)
        return x if pre_logits else self.fc(x)


class Net(nn.Module):
    def __init__(self, block, settings, in_chans=3, num_classes=1000, drop_rate=0.0, norm_layer: Optional[Callable[..., nn.Module]] = None, down_type='avg', **kwargs):
        super().__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.num_classes = num_classes
        self.conv_stem = nn.Conv2d(in_chans, 8, kernel_size=3, stride=2, padding=1, bias=False)
        self.bn1 = norm_layer(8)
        self.act1 = nn.ReLU()
        in_ch = 8
        self.feature_info = []
        for idx, (planes, n, stride) in enumerate(settings):
            blocks = []
            downsample = None
            if stride != 1 or in_ch != planes * block.expansion:
                down_fn = downsample_avg if down_type == "avg" else downsample_conv
                downsample = down_fn(in_ch, planes * block.expansion, stride, norm_layer)
            blocks.append(block(in_ch, planes, stride, downsample))
            in_ch = planes * block.expansion
            for _ in range(1, n):
                blocks.append(block(in_ch, planes))
            self.add_module(f"stage{idx + 1}", nn.Sequential(*blocks))
            self.feature_info.append(dict(num_chs=in_ch, module=f"stage{idx + 1}"))
        self.num_stages = len(settings)
        self.num_features = in_ch
        self.head = Head(in_ch, num_classes, drop_rate=drop_rate)

    def forward_features(self, inp):
        torch._assert(inp.dim() == 4, f"expected a 4D input, got {inp.dim()}D")
        inp = self.conv_stem(inp)
        inp = self.bn1(inp)
        inp = self.act1(inp)
        for i in range(self.num_stages):
            inp = getattr(self, f"stage{i + 1}")(inp)
        return inp

    def forward_head(self, inp, pre_logits: bool = False):
        return self.head(inp, pre_logits=pre_logits)

    def forward(self, inp):
        inp = self.forward_features(inp)
        inp = self.forward_head(inp)
        return inp


def create_net(variant="small", **kwargs):
    cfgs = {"small": [(8, 3, 1), (16, 3, 2), (32, 3, 2), (64, 3, 2), (128, 3, 2)], "base": [(8, 4, 1), (16, 4, 2), (32, 4, 2), (64, 4, 2), (128, 4, 2)]}
    return Net(ResBlock, cfgs[variant], **kwargs)


