import torch
import torch.nn as nn
import torch.nn.functional as F
from collections import OrderedDict


class SqueezeExpand(nn.Module):
    def __init__(self, inplanes, squeeze_planes, expand1x1_planes, expand3x3_planes):
        super().__init__()
        self.inplanes = inplanes
        self.sq = nn.Conv2d(inplanes, squeeze_planes, kernel_size=1)
        self.ex1 = nn.Conv2d(squeeze_planes, expand1x1_planes, kernel_size=1)
        self.ex3 = nn.Conv2d(squeeze_planes, expand3x3_planes, kernel_size=3, padding=1)

    def forward(self, inp):
        inp = F.relu6(self.sq(inp), inplace=True)
        return torch.cat(
            [F.relu6(self.ex1(inp), inplace=True), F.relu6(self.ex3(inp), inplace=True)], 1
        )


class Model(nn.Module):
    def __init__(self, stage_cfg, in_chans=3, num_classes=10, drop_rate=0.0, norm_layer=None, output_stride=32, **kwargs):
        super().__init__()
        assert output_stride in (8, 16, 32)
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.num_classes = num_classes
        self.stem = nn.Sequential(OrderedDict([
            ("conv", nn.Conv2d(in_chans, 16, kernel_size=3, stride=2, padding=1, bias=False)),
            ("bn", norm_layer(16)),
            ("act", nn.ReLU6(inplace=True)),
        ]))
        in_ch = 16
        self.feature_info = []
        stages = []
        for idx, (sq, e, n) in enumerate(stage_cfg):
            blocks = []
            if idx > 0:
                blocks.append(nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True))
            for _ in range(n):
                blocks.append(SqueezeExpand(in_ch, sq, e, e))
                in_ch = 2 * e
            stages.append(nn.Sequential(*blocks))
            self.feature_info.append(dict(num_chs=in_ch, module=f"stages.{idx}"))
        self.stages = nn.Sequential(*stages)
        self.num_features = in_ch
        self.drop = nn.Dropout(drop_rate)
        self.fc = nn.Linear(in_ch, num_classes)

    def forward(self, inp):
        torch._assert(inp.dim() == 4, f"expected a 4D input, got {inp.dim()}D")
        inp = self.stem(inp)
        inp = self.stages(inp)
        inp = F.adaptive_avg_pool2d(inp, 1)
        inp = torch.flatten(inp, 1)
        inp = self.drop(inp)
        return self.fc(inp)


def _model(variant, weights=None, progress=True, **kwargs):
    cfgs = {"small": [(8, 32, 3), (16, 64, 1), (24, 96, 3), (32, 128, 1), (40, 160, 2)]}
    model = Model(cfgs[variant], **kwargs)
    if weights is not None:
        model.load_state_dict(weights.get_state_dict(progress=progress))
    return model


def make_model(weights=None, progress=True, **kwargs):
    return _model('small', weights, progress, **kwargs)


