import torch
from torch import nn
from torch.nn import functional as F
from functools import partial


def conv3(in_planes, out_planes, stride=1, groups=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=3, stride=stride, padding=1,
                     groups=groups, bias=False)


def conv1(in_planes, out_planes, stride=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=1, stride=stride, bias=False)


class Bottleneck(nn.Module):
    expansion = 4

    def __init__(self, inplanes, planes, stride=1, proj=None, norm_layer=None):
        super().__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.c1 = conv1(inplanes, planes)
        self.bn1 = norm_layer(planes)
        self.c2 = conv3(planes, planes, stride)
        self.bn2 = norm_layer(planes)
        self.c3 = conv1(planes, planes * self.expansion)
        self.bn3 = norm_layer(planes * self.expansion)
        self.relu1 = nn.ReLU(inplace=True)
        self.relu2 = nn.ReLU(inplace=True)
        self.relu3 = nn.ReLU(inplace=True)
        self.proj = proj
        self.stride = stride

    def forward(self, feats):
        residual = feats

        y = self.c1(feats)
        y = self.bn1(y)
        y = self.relu1(y)
        y = self.c2(y)
        y = self.bn2(y)
        y = self.relu2(y)
        y = self.c3(y)
        y = self.bn3(y)

        if self.proj is not None:
            residual = self.proj(feats)

        y += residual
        y = self.relu3(y)
        return y


def conv3x3(in_planes, out_planes, stride=1, groups=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=3, stride=stride, padding=1,
                     groups=groups, bias=False)


def conv1x1(in_planes, out_planes, stride=1):
    return nn.Conv2d(in_planes, out_planes, kernel_size=1, stride=stride, bias=False)


class ResBlock(nn.Module):
    expansion = 1

    def __init__(self, inplanes, planes, stride=1, shortcut=None, norm_layer=None):
        super().__init__()
        if norm_layer is None:
            norm_layer = nn.BatchNorm2d
        self.conv_a = conv3x3(inplanes, planes, stride)
        self.bn_a = norm_layer(planes)
        self.conv_b = conv3x3(planes, planes)
        self.bn_b = norm_layer(planes)
        self.relu1 = nn.ReLU(inplace=True)
        self.relu2 = nn.ReLU(inplace=True)
        self.shortcut = shortcut
        self.stride = stride

    def forward(self, feats):
        identity = feats

        h = self.conv_a(feats)
        h = self.bn_a(h)
        h = self.relu1(h)
        h = self.conv_b(h)
        h = self.bn_b(h)

        if self.shortcut is not None:
            identity = self.shortcut(feats)

        h += identity
        h = self.relu2(h)
        return h


def downsample_conv(in_chs, out_chs, stride=1, norm_layer=None):
    if norm_layer is None:
        norm_layer = nn.BatchNorm2d
    return nn.Sequential(nn.Conv2d(in_chs, out_chs, kernel_size=1, stride=stride, bias=False), norm_layer(out_chs))


def downsample_avg(in_chs, out_chs, stride=1, norm_layer=None):
    if norm_layer is None:
        norm_layer = nn.BatchNorm2d
    pool = nn.AvgPool2d(2, stride, ceil_mode=True, count_include_pad=False) if stride > 1 else nn.Identity()
    return nn.Sequential(pool, nn.Conv2d(in_chs, out_chs, kernel_size=1, stride=1, bias=False), norm_layer(out_chs))


class FireModule(nn.Module):
    def __init__(self, inplanes, squeeze_planes, expand1x1_planes, expand3x3_planes):
        super().__init__()
        self.inplanes = inplanes
        self.reduce = nn.Conv2d(inplanes, squeeze_planes, kernel_size=1)
        self.expand_a = nn.Conv2d(squeeze_planes, expand1x1_planes, kernel_size=1)
        self.expand_b = nn.Conv2d(squeeze_planes, expand3x3_planes, kernel_size=3, padding=1)
        self.squeeze_activation = nn.ReLU(inplace=True)
        self.expand1x1_activation = nn.ReLU(inplace=True)
        self.expand3x3_activation = nn.ReLU(inplace=True)

    def forward(self, feats):
        feats = self.squeeze_activation(self.reduce(feats))
        return torch.cat(
            [self.expand1x1_activation(self.expand_a(feats)), self.expand3x3_activation(self.expand_b(feats))], 1
        )


class NormMlpHead(nn.Module):
    def __init__(self, in_features, num_classes, drop_rate=0.0):
        super().__init__()

        self.flatten = nn.Flatten(1)
        self.drop = nn.Dropout(drop_rate)
        self.fc = nn.Linear(in_features, num_classes) if num_classes > 0 else nn.Identity()

    def forward(self, x, pre_logits: bool = False):
        x = x.mean((2, 3), keepdim=True)
        x = self.flatten(x)
        x = self.drop(x)
        return x if pre_logits else self.fc(x)


class Net(nn.Module):
    def __init__(self, block, stem_stages, main_stages, in_chans=3, num_classes=1000, drop_rate=0.0, norm_layer=None, down_type='conv', output_stride=32):
        super().__init__()
        assert output_stride in (8, 16, 32)
        if norm_layer is None:
            norm_layer = partial(nn.BatchNorm2d, eps=1e-3)
        self.num_classes = num_classes
        self.conv_stem = nn.Conv2d(in_chans, 8, kernel_size=3, stride=2, padding=1, bias=False)
        self.bn1 = norm_layer(8)
        self.act1 = nn.ReLU(inplace=True)
        in_ch = 8
        self.stages = nn.ModuleList()
        for idx, (planes, n, stride) in enumerate(stem_stages):
            blocks = []
            downsample = None
            if stride != 1 or in_ch != planes * block.expansion:
                down_fn = downsample_avg if down_type == "avg" else downsample_conv
                downsample = down_fn(in_ch, planes * block.expansion, stride, norm_layer)
            blocks.append(block(in_ch, planes, stride, downsample))
            in_ch = planes * block.expansion
            for _ in range(1, n):
                blocks.append(block(in_ch, planes))
            self.stages.append(nn.Sequential(*blocks))
        for idx, (sq, e, n) in enumerate(main_stages, start=len(stem_stages)):
            blocks = []
            if idx > 0:
                blocks.append(nn.MaxPool2d(kernel_size=3, stride=2, ceil_mode=True))
            for _ in range(n):
                blocks.append(FireModule(in_ch, sq, e, e))
                in_ch = 2 * e
            self.stages.append(nn.Sequential(*blocks))
        self.head = NormMlpHead(in_ch, num_classes, drop_rate=drop_rate)

    def forward_features(self, feats):
        feats = self.conv_stem(feats)
        feats = self.bn1(feats)
        feats = self.act1(feats)
        for stage in self.stages:
            feats = stage(feats)
        return feats

    def forward_head(self, feats, pre_logits: bool = False):
        return self.head(feats, pre_logits=pre_logits)

    def forward(self, feats):
        feats = self.forward_features(feats)
        feats = self.forward_head(feats)
        return feats


def create_net(variant="small", **kwargs):
    cfgs = {"small": ([(8, 1, 1), (16, 3, 2)], [(24, 96, 1)])}
    return Net(Bottleneck, *cfgs[variant], **kwargs)


